// GENERATED FILE. Source of truth: docs/data/biblia-emanus/*.json
import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 6,
  code: "JOS",
  name: "Iosua",
  chapters: {
    1: ["După moartea lui Moise, slujitorul DOMNULUI, DOMNUL i-a vorbit lui Iosua, fiul lui Nun, slujitorul lui Moise, spunând:", "„Moise, slujitorul Meu, a murit. Acum ridică-te, treci Iordanul acesta, tu și tot poporul acesta, spre țara pe care le-o dau fiilor lui Israel.", "Ți-am dat orice loc pe care-l va călca talpa piciorului tău, așa cum i-am spus lui Moise.", "Hotarul vostru va fi de la pustie și Libanul acesta până la râul cel mare, râul Eufrat, cuprinzând toată țara hitiților, și până la Marea cea Mare, spre apus.", "Nimeni nu va putea să stea înaintea ta în toate zilele vieții tale. Cum am fost cu Moise, așa voi fi și cu tine. Nu te voi lăsa și nu te voi părăsi.", "Fii tare și curajos, căci tu vei da acestui popor ca moștenire țara pe care am jurat părinților lor că le-o voi da.", "Numai fii tare și foarte curajos, având grijă să împlinești toată Legea pe care ți-a poruncit-o Moise, slujitorul Meu. Nu te abate de la ea nici la dreapta, nici la stânga, ca să lucrezi cu înțelepciune oriunde vei merge.", "Cartea aceasta a Legii să nu se depărteze de gura ta. Cugetă la ea zi și noapte, ca să ai grijă să împlinești tot ce este scris în ea; atunci îți vei duce calea la bun sfârșit și vei lucra cu înțelepciune.", "Nu ți-am poruncit Eu? Fii tare și curajos! Nu te înspăimânta și nu te descuraja, căci DOMNUL, Dumnezeul tău, este cu tine oriunde vei merge.”", "Iosua le-a poruncit conducătorilor poporului:", "„Treceți prin tabără și porunciți poporului: «Pregătiți-vă provizii, căci peste trei zile veți trece Iordanul acesta, ca să intrați și să luați în stăpânire țara pe care DOMNUL, Dumnezeul vostru, v-o dă s-o stăpâniți.»”", "Iar rubeniților, gadiților și jumătății seminției lui Manase, Iosua le-a spus:", "„Aduceți-vă aminte de cuvântul pe care vi l-a poruncit Moise, slujitorul DOMNULUI: «DOMNUL, Dumnezeul vostru, vă dă odihnă și vă dă țara aceasta.", "Soțiile, copiii și turmele voastre să rămână în țara pe care v-a dat-o Moise dincolo de Iordan. Dar voi, toți războinicii viteji, să treceți înarmați înaintea fraților voștri și să-i ajutați,", "până când DOMNUL le va da odihnă fraților voștri, ca și vouă, și vor lua și ei în stăpânire țara pe care DOMNUL, Dumnezeul vostru, le-o dă. Apoi vă veți întoarce în țara moștenirii voastre și o veți stăpâni, țara pe care v-a dat-o Moise, slujitorul DOMNULUI, dincolo de Iordan, spre răsărit.»”", "Ei i-au răspuns lui Iosua: „Vom face tot ce ne-ai poruncit și vom merge oriunde ne vei trimite.", "Te vom asculta în toate, așa cum l-am ascultat pe Moise. Numai DOMNUL, Dumnezeul tău, să fie cu tine, așa cum a fost cu Moise.", "Oricine se va răzvrăti împotriva poruncii tale și nu va asculta cuvintele tale în tot ce-i vei porunci va fi omorât. Numai fii tare și curajos!”"],
    2: ["Iosua, fiul lui Nun, a trimis în ascuns din Șitim doi bărbați ca iscoade, spunând: „Mergeți și cercetați țara, mai ales Ierihonul.” Ei au plecat și au intrat în casa unei prostituate pe nume Rahav și au rămas acolo.", "Regelui Ierihonului i s-a spus: „Iată, niște bărbați dintre fiii lui Israel au venit aici în noaptea aceasta ca să cerceteze țara.”", "Regele Ierihonului a trimis vorbă Rahavei: „Scoate-i pe bărbații care au venit la tine și au intrat în casa ta, fiindcă au venit să cerceteze toată țara.”", "Femeia i-a luat pe cei doi bărbați și i-a ascuns. Apoi a spus: „Da, bărbații au venit la mine, dar nu știam de unde erau.", "Pe când urma să se închidă poarta, la căderea întunericului, bărbații au ieșit. Nu știu unde s-au dus. Urmăriți-i repede și îi veți ajunge.”", "Dar ea îi urcase pe acoperiș și îi ascunsese sub tulpinile de in pe care le așezase pe acoperiș.", "Oamenii i-au urmărit pe drumul spre vadurile Iordanului, iar poarta s-a închis îndată ce urmăritorii au ieșit.", "Înainte ca iscoadele să se culce, Rahav s-a urcat la ele pe acoperiș", "și le-a spus: „Știu că DOMNUL v-a dat țara și că groaza de voi a căzut peste noi, iar toți locuitorii țării și-au pierdut curajul înaintea voastră.", "Căci am auzit cum DOMNUL a secat înaintea voastră apele Mării Roșii, când ați ieșit din Egipt, și ce le-ați făcut celor doi regi ai amoriților de dincolo de Iordan, lui Sihon și lui Og, pe care i-ați dat nimicirii.", "Când am auzit, ni s-au topit inimile și nimănui nu i-a mai rămas curaj din cauza voastră, căci DOMNUL, Dumnezeul vostru, este Dumnezeu sus în ceruri și jos pe pământ.", "Acum, vă rog, jurați-mi pe DOMNUL că, așa cum eu m-am purtat cu bunătate statornică față de voi, vă veți purta și voi cu bunătate statornică față de casa tatălui meu. Dați-mi un semn de încredere.", "că îi veți lăsa în viață pe tatăl meu, pe mama mea, pe frații mei, pe surorile mele și pe toți ai lor și că ne veți scăpa viața de la moarte.”", "Bărbații i-au răspuns: „Viața noastră pentru viața voastră, dacă nu dezvăluiți această înțelegere a noastră. Când DOMNUL ne va da țara, ne vom purta față de tine cu bunătate statornică și credincioșie.”", "Ea i-a coborât cu o frânghie pe fereastră, căci casa ei era lipită de zidul cetății; locuia chiar în zid.", "Ea le-a spus: „Mergeți spre munte, ca să nu vă întâlnească urmăritorii. Ascundeți-vă acolo trei zile, până se vor întoarce urmăritorii; apoi vă veți putea continua drumul.”", "Bărbații i-au spus: „Vom fi nevinovați față de jurământul acesta pe care ne-ai pus să-l facem,", "dacă, atunci când vom intra în țară, nu vei lega la fereastra prin care ne-ai coborât această funie din fir stacojiu și nu-i vei strânge în casa ta pe tatăl tău, pe mama ta, pe frații tăi și toată casa tatălui tău.", "Oricine va ieși pe ușile casei tale în stradă va răspunde cu sângele său, iar noi vom fi nevinovați. Dar dacă va pune cineva mâna pe vreunul dintre cei care vor fi cu tine în casă, sângele lui va fi asupra capului nostru.", "Dacă însă vei dezvălui această înțelegere a noastră, vom fi dezlegați de jurământul pe care ne-ai pus să-l facem.”", "Ea a răspuns: „Să fie după cuvintele voastre.” Apoi i-a lăsat să plece, iar ei au plecat. Ea a legat funia stacojie la fereastră.", "Ei au mers la munte și au rămas acolo trei zile, până s-au întors urmăritorii. Urmăritorii i-au căutat pe tot drumul, dar nu i-au găsit.", "Cei doi bărbați s-au întors, au coborât de pe munte, au trecut Iordanul și au venit la Iosua, fiul lui Nun. I-au povestit tot ce li se întâmplase.", "Ei i-au spus lui Iosua: „Cu adevărat, DOMNUL a dat toată țara în mâinile noastre; toți locuitorii țării și-au pierdut curajul înaintea noastră.”"],
    3: ["Iosua s-a sculat dis-de-dimineață. El și toți fiii lui Israel au pornit din Șitim și au ajuns la Iordan. Au rămas acolo înainte să treacă.", "După trei zile, conducătorii au trecut prin tabără", "și au poruncit poporului: „Când veți vedea chivotul legământului DOMNULUI, Dumnezeul vostru, purtat de preoții leviți, să plecați din locul vostru și să mergeți după el.", "Dar între voi și el să fie o distanță de aproape două mii de coți. Să nu vă apropiați de el, ca să cunoașteți drumul pe care trebuie să mergeți, fiindcă nu ați mai trecut pe drumul acesta.”", "Iosua a spus poporului: „Sfințiți-vă, căci mâine DOMNUL va face lucruri minunate în mijlocul vostru.”", "Apoi Iosua le-a spus preoților: „Ridicați chivotul legământului și treceți înaintea poporului.” Ei au ridicat chivotul legământului și au mers înaintea poporului.", "DOMNUL i-a spus lui Iosua: „Astăzi voi începe să te înalț în ochii întregului Israel, ca să știe că, așa cum am fost cu Moise, voi fi și cu tine.", "Poruncește-le preoților care poartă chivotul legământului: «Când veți ajunge la marginea apelor Iordanului, opriți-vă în Iordan.»”", "Iosua le-a spus fiilor lui Israel: „Apropiați-vă și ascultați cuvintele DOMNULUI, Dumnezeul vostru.”", "Iosua a spus: „Prin aceasta veți ști că Dumnezeul cel viu este în mijlocul vostru și că îi va alunga cu siguranță dinaintea voastră pe canaaniți, hitiți, hiviți, periziți, ghirgașiți, amoriți și iebusiți.", "Iată, chivotul legământului Stăpânului întregului pământ trece înaintea voastră prin Iordan.", "Luați acum doisprezece bărbați din semințiile lui Israel, câte unul din fiecare seminție.", "Când tălpile picioarelor preoților care poartă chivotul DOMNULUI, Stăpânul întregului pământ, se vor opri în apele Iordanului, apele care coboară din amonte vor fi oprite și se vor ridica într-o singură grămadă.”", "Când poporul a plecat din corturi ca să treacă Iordanul, preoții care purtau chivotul legământului mergeau înaintea poporului.", "Când purtătorii chivotului au ajuns la Iordan și picioarele preoților care purtau chivotul s-au afundat în marginea apei — Iordanul se revărsa peste toate malurile lui în tot timpul secerișului —", "apele care coborau din amonte s-au oprit și s-au ridicat într-o singură grămadă, foarte departe, la Adam, cetatea de lângă Țaretan. Iar apele care coborau spre marea Arabei, Marea Sărată, au fost oprite în întregime. Poporul a trecut în dreptul Ierihonului.", "Preoții care purtau chivotul legământului DOMNULUI au stat neclintiți pe uscat, în mijlocul Iordanului, iar tot Israelul a trecut pe uscat, până când întregul popor a terminat de trecut Iordanul."],
    4: ["După ce întregul popor a terminat de trecut Iordanul, DOMNUL i-a spus lui Iosua:", "„Luați doisprezece bărbați din popor, câte unul din fiecare seminție,", "și porunciți-le: «Luați de aici, din mijlocul Iordanului, din locul unde au stat neclintite picioarele preoților, douăsprezece pietre. Duceți-le cu voi și așezați-le în locul unde veți înnopta.»”", "Iosua i-a chemat pe cei doisprezece bărbați pe care îi pregătise dintre fiii lui Israel, câte unul din fiecare seminție,", "și le-a spus: „Treceți înaintea chivotului DOMNULUI, Dumnezeul vostru, în mijlocul Iordanului. Fiecare să ridice pe umăr câte o piatră, după numărul semințiilor fiilor lui Israel.", "Ele să fie un semn în mijlocul vostru. Când copiii voștri vă vor întreba în viitor: «Ce înseamnă pentru voi pietrele acestea?»,", "să le spuneți: «Apele Iordanului au fost oprite înaintea chivotului legământului DOMNULUI. Când chivotul a trecut Iordanul, apele Iordanului au fost oprite.» Pietrele acestea vor fi pentru totdeauna o aducere-aminte pentru fiii lui Israel.”", "Fiii lui Israel au făcut așa cum le poruncise Iosua. Au luat douăsprezece pietre din mijlocul Iordanului, așa cum îi spusese DOMNUL lui Iosua, după numărul semințiilor fiilor lui Israel. Le-au dus cu ei până la locul unde au înnoptat și le-au așezat acolo.", "Iosua a ridicat douăsprezece pietre în mijlocul Iordanului, în locul unde stătuseră picioarele preoților care purtau chivotul legământului. Ele sunt acolo până în ziua de astăzi.", "Preoții care purtau chivotul au rămas în mijlocul Iordanului până s-a împlinit tot ce îi poruncise DOMNUL lui Iosua să spună poporului, potrivit cu tot ce îi poruncise Moise lui Iosua. Poporul s-a grăbit să treacă.", "După ce întregul popor a terminat de trecut, chivotul DOMNULUI și preoții au trecut sub privirile poporului.", "Fiii lui Ruben, fiii lui Gad și jumătatea seminției lui Manase au trecut înarmați înaintea fiilor lui Israel, așa cum le spusese Moise.", "Aproape patruzeci de mii de oameni înarmați pentru luptă au trecut înaintea DOMNULUI spre câmpiile Ierihonului, pregătiți de război.", "În ziua aceea, DOMNUL l-a înălțat pe Iosua în ochii întregului Israel. Ei s-au temut de el în toate zilele vieții lui, așa cum se temuseră de Moise.", "DOMNUL i-a spus lui Iosua:", "„Poruncește-le preoților care poartă chivotul mărturiei să iasă din Iordan.”", "Iosua le-a poruncit preoților: „Ieșiți din Iordan!”", "Când preoții care purtau chivotul legământului DOMNULUI au ieșit din mijlocul Iordanului și tălpile picioarelor lor au atins uscatul, apele Iordanului s-au întors la locul lor și s-au revărsat peste toate malurile lui, ca mai înainte.", "Poporul a ieșit din Iordan în ziua a zecea a lunii întâi și și-a așezat tabăra la Ghilgal, la marginea de răsărit a Ierihonului.", "Iosua a ridicat la Ghilgal cele douăsprezece pietre pe care le luaseră din Iordan.", "El le-a spus fiilor lui Israel: „Când copiii voștri îi vor întreba în viitor pe părinții lor: «Ce înseamnă pietrele acestea?»,", "să le faceți cunoscut copiilor voștri: «Israel a trecut Iordanul acesta pe uscat.»", "Căci DOMNUL, Dumnezeul vostru, a secat apele Iordanului dinaintea voastră până ați trecut, așa cum DOMNUL, Dumnezeul vostru, a făcut cu Marea Roșie, pe care a secat-o dinaintea noastră până am trecut,", "pentru ca toate popoarele pământului să cunoască faptul că mâna DOMNULUI este puternică și ca voi să vă temeți întotdeauna de DOMNUL, Dumnezeul vostru.”"],
    5: ["Când toți regii amoriților de dincolo de Iordan, spre apus, și toți regii canaaniților de lângă mare au auzit că DOMNUL secase apele Iordanului dinaintea fiilor lui Israel până când ei au trecut, inimile li s-au topit și nu le-a mai rămas curaj din cauza fiilor lui Israel.", "În vremea aceea, DOMNUL i-a spus lui Iosua: „Fă-ți cuțite de cremene și circumcide-i din nou pe fiii lui Israel, a doua oară.”", "Iosua și-a făcut cuțite de cremene și i-a circumcis pe fiii lui Israel la Dealul Prepuțurilor.", "Iată motivul pentru care Iosua i-a circumcis: toți bărbații apți de război care ieșiseră din Egipt muriseră în pustie, pe drum, după ieșirea din Egipt.", "Toți cei care ieșiseră din Egipt fuseseră circumciși, dar niciunul dintre cei născuți în pustie, pe drum, după ieșirea din Egipt, nu fusese circumcis.", "Fiii lui Israel umblaseră patruzeci de ani prin pustie, până când a pierit întreaga generație a bărbaților apți de război care ieșiseră din Egipt, fiindcă nu ascultaseră glasul DOMNULUI. DOMNUL le jurase că nu-i va lăsa să vadă țara pe care jurase părinților lor că ne-o va da, o țară în care curge lapte și miere.", "În locul lor i-a ridicat pe fiii lor. Pe aceștia i-a circumcis Iosua, căci erau necircumciși, fiindcă nu-i circumciseseră pe drum.", "După ce întregul popor a fost circumcis, au rămas în locurile lor din tabără până s-au vindecat.", "DOMNUL i-a spus lui Iosua: „Astăzi am rostogolit de peste voi rușinea Egiptului.” De aceea locul acela a fost numit Ghilgal până în ziua de astăzi.", "Fiii lui Israel și-au așezat tabăra la Ghilgal și au sărbătorit Paștele în seara zilei a paisprezecea a lunii, în câmpiile Ierihonului.", "În ziua de după Paște, chiar în ziua aceea, au mâncat din roadele țării: azime și grăunțe prăjite.", "Mana a încetat în ziua următoare, după ce au mâncat din roadele țării. Fiii lui Israel nu au mai avut mană, ci în anul acela au mâncat din recolta țării Canaanului.", "Pe când Iosua era lângă Ierihon, și-a ridicat privirea și a văzut un bărbat stând înaintea lui, cu sabia scoasă în mână. Iosua s-a apropiat de el și l-a întrebat: „Ești de partea noastră sau de partea dușmanilor noștri?”", "El a răspuns: „Nu, ci Eu sunt Căpetenia oștirii DOMNULUI; acum am venit.” Iosua a căzut cu fața la pământ, s-a plecat înaintea lui și l-a întrebat: „Ce îi spune stăpânul meu slujitorului său?”", "Căpetenia oștirii DOMNULUI i-a spus lui Iosua: „Scoate-ți sandalele din picioare, căci locul pe care stai este sfânt.” Și Iosua a făcut așa."],
    6: ["Ierihonul era închis și bine păzit din cauza fiilor lui Israel. Nimeni nu ieșea și nimeni nu intra.", "DOMNUL i-a spus lui Iosua: „Iată, am dat în mâna ta Ierihonul, împreună cu regele lui și cu războinicii lui viteji.", "Toți oamenii de război să înconjoare cetatea, dându-i ocol o dată. Așa să faci timp de șase zile.", "Șapte preoți să poarte înaintea chivotului șapte trâmbițe din coarne de berbec. În ziua a șaptea să înconjurați cetatea de șapte ori, iar preoții să sune din trâmbițe.", "Când vor suna prelung din cornul de berbec și veți auzi sunetul trâmbiței, tot poporul să scoată un strigăt puternic. Atunci zidul cetății se va prăbuși la locul lui, iar poporul va urca, fiecare drept înainte.”", "Iosua, fiul lui Nun, i-a chemat pe preoți și le-a spus: „Ridicați chivotul legământului, iar șapte preoți să poarte șapte trâmbițe din coarne de berbec înaintea chivotului DOMNULUI.”", "Apoi i-a spus poporului: „Porniți și înconjurați cetatea, iar oamenii înarmați să treacă înaintea chivotului DOMNULUI.”", "După ce Iosua a vorbit poporului, cei șapte preoți care purtau cele șapte trâmbițe din coarne de berbec înaintea DOMNULUI au pornit, sunând din trâmbițe, iar chivotul legământului DOMNULUI venea în urma lor.", "Oamenii înarmați mergeau înaintea preoților care sunau din trâmbițe, iar ariergarda venea în urma chivotului. Trâmbițele sunau în timp ce mergeau.", "Iosua poruncise poporului: „Să nu strigați, să nu vi se audă glasul și să nu vă iasă niciun cuvânt din gură până în ziua când vă voi spune: «Strigați!» Atunci să strigați.”", "Chivotul DOMNULUI a înconjurat cetatea, dându-i ocol o dată. Apoi au intrat în tabără și au rămas acolo peste noapte.", "Iosua s-a sculat dis-de-dimineață, iar preoții au ridicat chivotul DOMNULUI.", "Cei șapte preoți care purtau cele șapte trâmbițe din coarne de berbec înaintea chivotului DOMNULUI mergeau fără oprire și sunau din trâmbițe. Oamenii înarmați mergeau înaintea lor, iar ariergarda venea după chivotul DOMNULUI. Trâmbițele sunau în timp ce mergeau.", "În ziua a doua au înconjurat cetatea o dată și s-au întors în tabără. Așa au făcut timp de șase zile.", "În ziua a șaptea s-au sculat în zorii zilei și au înconjurat cetatea în același fel de șapte ori. Numai în ziua aceea au înconjurat cetatea de șapte ori.", "A șaptea oară, când preoții au sunat din trâmbițe, Iosua a spus poporului: „Strigați, căci DOMNUL v-a dat cetatea!", "Cetatea și tot ce este în ea să fie date DOMNULUI spre nimicire. Numai prostituata Rahav să rămână în viață, ea și toți cei care sunt cu ea în casă, pentru că i-a ascuns pe mesagerii pe care i-am trimis.", "Dar voi să vă păziți de lucrurile date spre nimicire, ca nu cumva, după ce le-ați pus deoparte pentru nimicire, să luați ceva din ele și astfel să faceți tabăra lui Israel vrednică de nimicire și s-o tulburați.", "Tot argintul, aurul și obiectele din bronz și fier sunt sfinte pentru DOMNUL; ele să intre în vistieria DOMNULUI.”", "Poporul a strigat, iar preoții au sunat din trâmbițe. Când poporul a auzit sunetul trâmbiței, a scos un strigăt puternic, iar zidul s-a prăbușit la locul lui. Poporul a urcat în cetate, fiecare drept înainte, și au cucerit cetatea.", "Au dat spre nimicire tot ce era în cetate, trecând prin ascuțișul sabiei bărbat și femeie, tânăr și bătrân, bou, oaie și măgar.", "Iosua le-a spus celor doi bărbați care cercetaseră țara: „Intrați în casa prostituatei și scoateți de acolo femeia și tot ce-i aparține, așa cum i-ați jurat.”", "Tinerii care fuseseră iscoade au intrat și au scos-o pe Rahav, pe tatăl ei, pe mama ei, pe frații ei și tot ce-i aparținea. Au scos întregul ei clan și i-au așezat în afara taberei lui Israel.", "Au ars cetatea și tot ce era în ea. Numai argintul, aurul și obiectele din bronz și fier le-au pus în vistieria Casei DOMNULUI.", "Iosua a lăsat-o în viață pe prostituata Rahav, împreună cu familia tatălui ei și cu tot ce-i aparținea. Ea a locuit în mijlocul lui Israel până în ziua de astăzi, pentru că i-a ascuns pe mesagerii trimiși de Iosua să cerceteze Ierihonul.", "În vremea aceea, Iosua a rostit un jurământ: „Blestemat înaintea DOMNULUI să fie omul care se va ridica să reconstruiască cetatea aceasta, Ierihonul! Cu prețul întâiului său născut îi va pune temeliile și cu prețul fiului său cel mai tânăr îi va așeza porțile.”", "DOMNUL a fost cu Iosua, iar faima lui s-a răspândit în toată țara."],
    7: ["Dar fiii lui Israel au încălcat porunca privitoare la lucrurile date spre nimicire. Acan, fiul lui Carmi, fiul lui Zabdi, fiul lui Zerah, din seminția lui Iuda, a luat din lucrurile date spre nimicire, iar mânia DOMNULUI s-a aprins împotriva fiilor lui Israel.", "Iosua a trimis oameni din Ierihon la Ai, care este lângă Bet-Aven, la răsărit de Betel, și le-a spus: „Urcați și cercetați țara.” Oamenii au urcat și au cercetat cetatea Ai.", "S-au întors la Iosua și i-au spus: „Să nu urce tot poporul. Să urce numai vreo două sau trei mii de oameni și să lovească cetatea Ai. Nu obosi tot poporul acolo, căci locuitorii ei sunt puțini.”", "Au urcat acolo aproximativ trei mii de oameni din popor, dar au fugit dinaintea oamenilor din Ai.", "Oamenii din Ai au ucis aproximativ treizeci și șase dintre ei. I-au urmărit de la poarta cetății până la Șebarim și i-au lovit pe coborâș. Inimile poporului s-au topit și au devenit ca apa.", "Iosua și-a sfâșiat hainele și a căzut cu fața la pământ înaintea chivotului DOMNULUI până seara, el și bătrânii lui Israel, și și-au presărat țărână pe cap.", "Iosua a spus: „Ah, Stăpâne DOAMNE, de ce ai trecut poporul acesta peste Iordan? Ca să ne dai în mâna amoriților și să ne nimicești? Mai bine ne-am fi mulțumit să rămânem dincolo de Iordan!", "Te rog, Stăpâne, ce să mai spun după ce Israel a fugit dinaintea dușmanilor săi?", "Cananiții și toți locuitorii țării vor auzi, ne vor înconjura și ne vor șterge numele de pe pământ. Atunci ce vei face pentru Numele Tău cel mare?”", "DOMNUL i-a spus lui Iosua: „Ridică-te! De ce stai căzut cu fața la pământ?", "Israel a păcătuit. Ei au încălcat legământul Meu, pe care li l-am poruncit. Au luat din lucrurile date spre nimicire, au furat, au ascuns și le-au pus printre lucrurile lor.", "De aceea fiii lui Israel nu pot sta înaintea dușmanilor lor. Ei fug dinaintea dușmanilor, pentru că au ajuns ei înșiși vrednici de nimicire. Nu voi mai fi cu voi dacă nu îndepărtați din mijlocul vostru lucrul dat spre nimicire.", "Ridică-te! Sfințește poporul și spune: «Sfințiți-vă pentru mâine, căci așa vorbește DOMNUL, Dumnezeul lui Israel: Este un lucru dat spre nimicire în mijlocul tău, Israel. Nu vei putea sta înaintea dușmanilor tăi până nu-l vei îndepărta din mijlocul tău.", "Dimineață să vă apropiați pe seminții. Seminția pe care o va arăta DOMNUL să se apropie pe clanuri; clanul pe care îl va arăta DOMNUL să se apropie pe familii; iar familia pe care o va arăta DOMNUL să se apropie om cu om.", "Cel care va fi arătat cu lucrul dat spre nimicire să fie ars în foc, el și tot ce are, pentru că a încălcat legământul DOMNULUI și a făcut o faptă rușinoasă în Israel.»”", "Iosua s-a sculat dis-de-dimineață și a adus Israelul aproape, seminție după seminție. A fost arătată seminția lui Iuda.", "A adus aproape clanurile lui Iuda și a fost arătat clanul zerahiților. A adus aproape clanul zerahiților, om cu om, și a fost arătat Zabdi.", "A adus aproape familia lui, om cu om, și a fost arătat Acan, fiul lui Carmi, fiul lui Zabdi, fiul lui Zerah, din seminția lui Iuda.", "Iosua i-a spus lui Acan: „Fiul meu, dă-I, te rog, glorie DOMNULUI, Dumnezeul lui Israel, și mărturisește înaintea Lui. Spune-mi acum ce ai făcut și nu ascunde nimic de mine.”", "Acan i-a răspuns lui Iosua: „Este adevărat, am păcătuit împotriva DOMNULUI, Dumnezeul lui Israel. Iată ce am făcut:", "Am văzut printre prăzi o mantie frumoasă din Șinear, două sute de șecheli de argint și un lingou de aur în greutate de cincizeci de șecheli. Le-am poftit și le-am luat. Iată, sunt ascunse în pământ, în mijlocul cortului meu, iar argintul este dedesubt.”", "Iosua a trimis mesageri, iar ei au alergat la cort. Lucrurile erau ascunse în cortul lui, cu argintul dedesubt.", "Le-au luat din mijlocul cortului, le-au adus la Iosua și la toți fiii lui Israel și le-au pus înaintea DOMNULUI.", "Iosua și tot Israelul împreună cu el l-au luat pe Acan, fiul lui Zerah, argintul, mantia, lingoul de aur, fiii și fiicele lui, boii, măgarii și oile lui, cortul și tot ce avea, și i-au dus în valea Acor.", "Iosua a spus: „De ce ne-ai tulburat? DOMNUL te va tulbura astăzi.” Tot Israelul l-a lovit cu pietre; apoi i-au ars în foc și au aruncat pietre peste ei.", "Au ridicat peste el o movilă mare de pietre, care a rămas până în ziua de astăzi. Atunci DOMNUL S-a întors din aprinderea mâniei Sale. De aceea locul acela a fost numit Valea Acor până în ziua de astăzi."],
    8: ["DOMNUL i-a spus lui Iosua: „Nu te teme și nu te descuraja. Ia cu tine tot poporul de război, ridică-te și urcă la Ai. Iată, am dat în mâna ta regele din Ai, poporul lui, cetatea lui și țara lui.", "Să faci cetății Ai și regelui ei cum ai făcut Ierihonului și regelui lui, numai că prada și animalele ei le puteți lua pentru voi. Pune o ambuscadă în spatele cetății.”", "Iosua s-a ridicat împreună cu tot poporul de război ca să urce la Ai. Iosua a ales treizeci de mii de războinici viteji și i-a trimis noaptea.", "Le-a poruncit: „Iată, să stați la pândă în spatele cetății. Să nu vă îndepărtați prea mult de cetate și să fiți cu toții gata.", "Eu și tot poporul care este cu mine ne vom apropia de cetate. Când vor ieși împotriva noastră, ca prima dată, vom fugi dinaintea lor.", "Ei vor ieși după noi până îi vom atrage departe de cetate, căci vor spune: «Fug dinaintea noastră ca prima dată!» Noi vom fugi dinaintea lor.", "Atunci voi să vă ridicați din ambuscadă și să luați cetatea, căci DOMNUL, Dumnezeul vostru, o va da în mâna voastră.", "După ce veți cuceri cetatea, să-i dați foc. Să faceți după cuvântul DOMNULUI. Iată, v-am poruncit.”", "Iosua i-a trimis, iar ei au mers la locul ambuscadei și au rămas între Betel și Ai, la apus de Ai. Iosua a rămas în noaptea aceea în mijlocul poporului.", "Iosua s-a sculat dis-de-dimineață, a numărat poporul și a urcat, el și bătrânii lui Israel, în fruntea poporului spre Ai.", "Tot poporul de război care era cu el a urcat, s-a apropiat și a ajuns în fața cetății. Și-au așezat tabăra la nord de Ai, având valea între ei și Ai.", "Iosua a luat aproximativ cinci mii de oameni și i-a pus în ambuscadă între Betel și Ai, la apus de cetate.", "Au așezat poporul, toată tabăra de la nordul cetății și ambuscada la apusul cetății. Iosua a mers în noaptea aceea în mijlocul văii.", "Când regele din Ai a văzut aceasta, el și oamenii cetății s-au grăbit și s-au sculat dis-de-dimineață. Au ieșit la timpul hotărât ca să lupte împotriva lui Israel, în fața Arabei, fără să știe că în spatele cetății era o ambuscadă.", "Iosua și tot Israelul s-au prefăcut învinși înaintea lor și au fugit pe drumul spre pustie.", "Tot poporul din cetate a fost chemat să-i urmărească. L-au urmărit pe Iosua și au fost atrași departe de cetate.", "Nu a rămas niciun bărbat în Ai sau în Betel care să nu fi ieșit după Israel. Au lăsat cetatea deschisă și au urmărit Israelul.", "DOMNUL i-a spus lui Iosua: „Întinde sulița pe care o ai în mână spre Ai, căci o voi da în mâna ta.” Iosua a întins sulița din mâna lui spre cetate.", "Oamenii din ambuscadă s-au ridicat repede din locul lor. De îndată ce el și-a întins mâna, au alergat, au intrat în cetate, au cucerit-o și s-au grăbit să-i dea foc.", "Când oamenii din Ai s-au uitat înapoi, au văzut fumul cetății ridicându-se spre cer. Nu mai aveau nicio cale de scăpare, nici într-o parte, nici în alta, iar poporul care fugise spre pustie s-a întors împotriva urmăritorilor.", "Când Iosua și tot Israelul au văzut că ambuscada cucerise cetatea și că fumul cetății se ridica, s-au întors și i-au omorât pe oamenii din Ai.", "Ceilalți au ieșit din cetate împotriva lor, astfel că oamenii din Ai au fost prinși în mijlocul lui Israel, unii de o parte și alții de cealaltă. Israel i-a lovit fără să lase vreun supraviețuitor sau fugar.", "Pe regele din Ai l-au prins viu și l-au adus la Iosua.", "După ce Israel a terminat de ucis toți locuitorii din Ai aflați pe câmp și în pustia unde îi urmăriseră, și după ce toți au căzut sub ascuțișul sabiei până au fost nimiciți, tot Israelul s-a întors la Ai și a trecut cetatea prin ascuțișul sabiei.", "Toți cei care au căzut în ziua aceea, bărbați și femei, au fost douăsprezece mii, toți locuitorii din Ai.", "Iosua nu și-a retras mâna cu care întinsese sulița până nu i-a dat spre nimicire pe toți locuitorii din Ai.", "Israel a luat pentru sine numai animalele și prada cetății, după cuvântul pe care DOMNUL i-l poruncise lui Iosua.", "Iosua a ars cetatea Ai și a făcut-o pentru totdeauna un morman de ruine, o pustietate până în ziua de astăzi.", "L-a spânzurat pe regele din Ai de un copac până seara. La apusul soarelui, Iosua a poruncit să-i coboare trupul de pe copac. L-au aruncat la intrarea porții cetății și au ridicat peste el o movilă mare de pietre, care a rămas până în ziua de astăzi.", "Atunci Iosua a construit pe muntele Ebal un altar pentru DOMNUL, Dumnezeul lui Israel,", "așa cum Moise, slujitorul DOMNULUI, le poruncise fiilor lui Israel și cum este scris în Cartea Legii lui Moise: un altar din pietre întregi, peste care nu fusese ridicată nicio unealtă de fier. Au adus pe el arderi-de-tot DOMNULUI și au jertfit jertfe de pace.", "Acolo, pe pietre, Iosua a scris o copie a Legii lui Moise, pe care a scris-o în prezența fiilor lui Israel.", "Tot Israelul, bătrânii, conducătorii și judecătorii lui, stăteau de o parte și de alta a chivotului, înaintea preoților leviți care purtau chivotul legământului DOMNULUI, atât străinul, cât și băștinașul. Jumătate stăteau în fața muntelui Garizim și jumătate în fața muntelui Ebal, așa cum poruncise mai înainte Moise, slujitorul DOMNULUI, ca poporul lui Israel să fie binecuvântat.", "După aceea, Iosua a citit toate cuvintele Legii, binecuvântarea și blestemul, după tot ce este scris în Cartea Legii.", "Nu a fost niciun cuvânt din tot ce poruncise Moise pe care Iosua să nu-l citească înaintea întregii adunări a lui Israel, inclusiv femeile, copiii și străinii care locuiau în mijlocul lor."],
    9: ["Când au auzit toți regii de dincolo de Iordan, din regiunea muntoasă, din zona deluroasă joasă și de pe tot țărmul Mării celei Mari, până în dreptul Libanului — hitiții, amoriții, cananiții, periziții, hiviții și iebusiții —", "s-au adunat cu toții ca să lupte împotriva lui Iosua și a lui Israel într-un singur gând.", "Dar locuitorii Gabaonului au auzit ce făcuse Iosua Ierihonului și cetății Ai.", "Au recurs și ei la viclenie: au mers și s-au dat drept trimiși. Au luat saci vechi pe măgari, burdufuri vechi de vin, crăpate și legate,", "sandale vechi și peticite în picioare și haine vechi pe ei. Toată pâinea lor pentru drum era uscată și mucegăită.", "Au venit la Iosua în tabăra de la Ghilgal și i-au spus lui și bărbaților lui Israel: „Venim dintr-o țară îndepărtată. Încheiați acum un legământ cu noi.”", "Bărbații lui Israel le-au spus hiviților: „Poate că locuiți în mijlocul nostru. Cum am putea încheia un legământ cu voi?”", "Ei i-au spus lui Iosua: „Suntem slujitorii tăi.” Iosua i-a întrebat: „Cine sunteți și de unde veniți?”", "Ei i-au răspuns: „Slujitorii tăi au venit dintr-o țară foarte îndepărtată, datorită Numelui DOMNULUI, Dumnezeul tău, căci am auzit faima Lui și tot ce a făcut în Egipt,", "precum și tot ce le-a făcut celor doi regi ai amoriților de dincolo de Iordan: lui Sihon, regele Heșbonului, și lui Og, regele Basanului, care era la Aștarot.", "Bătrânii noștri și toți locuitorii țării noastre ne-au spus: «Luați provizii pentru drum, mergeți să-i întâlniți și spuneți-le: Suntem slujitorii voștri; încheiați acum un legământ cu noi.»", "Iată pâinea noastră. Era caldă când am luat-o din case în ziua în care am pornit spre voi, iar acum este uscată și mucegăită.", "Aceste burdufuri de vin erau noi când le-am umplut, iar acum sunt crăpate. Hainele și sandalele noastre s-au învechit din cauza drumului foarte lung.”", "Bărbații lui Israel au luat din proviziile lor, dar nu au cerut sfat din gura DOMNULUI.", "Iosua a făcut pace cu ei și a încheiat un legământ prin care îi lăsa în viață, iar conducătorii adunării le-au jurat.", "La trei zile după ce încheiaseră legământul cu ei, au auzit că erau vecinii lor și că locuiau în mijlocul lor.", "Fiii lui Israel au pornit și au ajuns la cetățile lor în ziua a treia. Cetățile lor erau Gabaon, Chefira, Beerot și Chiriat-Iearim.", "Fiii lui Israel nu i-au lovit, pentru că liderii adunării le juraseră pe DOMNUL, Dumnezeul lui Israel. Atunci întreaga adunare a murmurat împotriva conducătorilor.", "Toți conducătorii au spus întregii adunări: „Le-am jurat pe DOMNUL, Dumnezeul lui Israel, de aceea nu ne putem atinge de ei.", "Iată ce le vom face: îi vom lăsa în viață, ca să nu vină mânia asupra noastră din cauza jurământului pe care li l-am făcut.”", "Conducătorii au spus despre ei: „Să trăiască!” Astfel au ajuns tăietori de lemne și cărători de apă pentru întreaga adunare, după cum le spuseseră conducătorii.", "Iosua i-a chemat și le-a spus: „De ce ne-ați înșelat spunând: «Locuim foarte departe de voi», când de fapt locuiți în mijlocul nostru?", "Acum sunteți blestemați și unii dintre voi nu veți înceta niciodată să fiți sclavi: tăietori de lemne și cărători de apă pentru Casa Dumnezeului meu.”", "Ei i-au răspuns lui Iosua: „Slujitorilor tăi li s-a spus limpede că DOMNUL, Dumnezeul tău, i-a poruncit slujitorului Său Moise să vă dea toată țara și să-i nimicească dinaintea voastră pe toți locuitorii ei. Ne-am temut foarte mult pentru viețile noastre din cauza voastră și de aceea am făcut lucrul acesta.", "Acum suntem în mâna ta. Fă-ne ce ți se pare bun și drept.”", "Iosua le-a făcut așa și i-a scăpat din mâna fiilor lui Israel, ca să nu-i omoare.", "În ziua aceea, Iosua i-a pus tăietori de lemne și cărători de apă pentru adunare și pentru altarul DOMNULUI, până în ziua de astăzi, în locul pe care avea să-l aleagă."],
    10: ["Când Adoni-Țedek, regele Ierusalimului, a auzit că Iosua cucerise cetatea Ai și o dăduse spre nimicire, făcând cetății Ai și regelui ei cum făcuse Ierihonului și regelui lui, și că locuitorii Gabaonului făcuseră pace cu Israel și rămăseseră în mijlocul lor,", "el și oamenii lui s-au temut foarte mult, pentru că Gabaon era o cetate mare, asemenea uneia dintre cetățile regale, mai mare decât Ai, iar toți bărbații ei erau viteji.", "Adoni-Țedek, regele Ierusalimului, le-a trimis vorbă lui Hoham, regele Hebronului, lui Piram, regele Iarmutului, lui Iafia, regele Lachișului, și lui Debir, regele Eglonului:", "„Urcați la mine și ajutați-mă! Să lovim Gabaonul, căci a făcut pace cu Iosua și cu fiii lui Israel.”", "Cei cinci regi ai amoriților — regele Ierusalimului, regele Hebronului, regele Iarmutului, regele Lachișului și regele Eglonului — s-au adunat și au urcat cu toate armatele lor. Și-au așezat tabăra împotriva Gabaonului și au pornit război împotriva lui.", "Oamenii din Gabaon au trimis la Iosua, în tabăra de la Ghilgal, spunând: „Nu-ți părăsi slujitorii! Urcă repede la noi, salvează-ne și ajută-ne, căci toți regii amoriților care locuiesc în regiunea muntoasă s-au adunat împotriva noastră.”", "Iosua a urcat de la Ghilgal, el și tot poporul de război împreună cu el, inclusiv toți războinicii viteji.", "DOMNUL i-a spus lui Iosua: „Nu te teme de ei, căci i-am dat în mâna ta. Niciunul dintre ei nu va putea sta înaintea ta.”", "Iosua a venit asupra lor pe neașteptate, după ce urcase toată noaptea de la Ghilgal.", "DOMNUL i-a aruncat în panică înaintea lui Israel, iar Israel i-a lovit cu o mare înfrângere la Gabaon, i-a urmărit pe drumul care urcă la Bet-Horon și i-a lovit până la Azeca și Macheda.", "Pe când fugeau dinaintea lui Israel și coborau de la Bet-Horon, DOMNUL a aruncat peste ei din cer pietre mari, până la Azeca, și au murit. Au murit mai mulți din cauza grindinei decât au ucis fiii lui Israel cu sabia.", "Atunci Iosua I-a vorbit DOMNULUI, în ziua când DOMNUL i-a dat pe amoriți înaintea fiilor lui Israel, și a spus în fața lui Israel: „Soare, oprește-te deasupra Gabaonului, iar tu, lună, deasupra văii Aialonului!”", "Soarele s-a oprit și luna a stat până când națiunea s-a răzbunat pe dușmanii ei. Nu este scris lucrul acesta în Cartea celui Drept? Soarele a stat în mijlocul cerului și nu s-a grăbit să apună aproape o zi întreagă.", "Nu a mai fost nicio zi ca aceea, nici înainte, nici după ea, când DOMNUL să asculte astfel glasul unui om, căci DOMNUL lupta pentru Israel.", "Iosua și tot Israelul împreună cu el s-au întors în tabăra de la Ghilgal.", "Cei cinci regi au fugit și s-au ascuns în peștera de la Macheda.", "Lui Iosua i s-a spus: „Cei cinci regi au fost găsiți ascunși în peștera de la Macheda.”", "Iosua a spus: „Rostogoliți pietre mari la intrarea peșterii și puneți oameni să-i păzească.", "Dar voi să nu vă opriți. Urmăriți-vă dușmanii și loviți-i din urmă. Nu-i lăsați să intre în cetățile lor, căci DOMNUL, Dumnezeul vostru, i-a dat în mâna voastră.”", "După ce Iosua și fiii lui Israel au terminat de-i lovit cu o înfrângere foarte mare, până i-au nimicit, cei care au supraviețuit au intrat în cetățile fortificate.", "Tot poporul s-a întors în pace la Iosua, în tabăra de la Macheda. Nimeni n-a îndrăznit să spună vreun cuvânt împotriva vreunuia dintre fiii lui Israel.", "Atunci Iosua a spus: „Deschideți intrarea peșterii și aduceți-i la mine pe cei cinci regi din peșteră.”", "Au făcut așa și i-au adus din peșteră pe cei cinci regi: regele Ierusalimului, regele Hebronului, regele Iarmutului, regele Lachișului și regele Eglonului.", "După ce i-au adus pe acești regi la Iosua, Iosua i-a chemat pe toți bărbații lui Israel și le-a spus comandanților oamenilor de război care merseseră cu el: „Apropiați-vă și puneți-vă picioarele pe grumazurile acestor regi.” Ei s-au apropiat și și-au pus picioarele pe grumazurile lor.", "Iosua le-a spus: „Nu vă temeți și nu vă descurajați. Fiți tari și curajoși, căci așa va face DOMNUL tuturor dușmanilor împotriva cărora veți lupta.”", "După aceea, Iosua i-a lovit și i-a omorât, apoi i-a spânzurat pe cinci copaci. Au rămas spânzurați pe copaci până seara.", "La apusul soarelui, Iosua a poruncit să fie coborâți de pe copaci și aruncați în peștera unde se ascunseseră. Au pus pietre mari la intrarea peșterii, care au rămas până în ziua de astăzi.", "În ziua aceea, Iosua a cucerit Macheda și a trecut-o prin ascuțișul sabiei, împreună cu regele ei. A dat spre nimicire cetatea și fiecare persoană din ea, fără să lase vreun supraviețuitor. I-a făcut regelui din Macheda cum îi făcuse regelui Ierihonului.", "Iosua a trecut de la Macheda la Libna, împreună cu tot Israelul, și a luptat împotriva Libnei.", "DOMNUL a dat-o și pe ea, împreună cu regele ei, în mâna lui Israel. Iosua a trecut-o prin ascuțișul sabiei, împreună cu fiecare persoană din ea, fără să lase vreun supraviețuitor. I-a făcut regelui ei cum îi făcuse regelui Ierihonului.", "Iosua a trecut de la Libna la Lachiș, împreună cu tot Israelul. Și-a așezat tabăra împotriva ei și a luptat împotriva ei.", "DOMNUL a dat Lachișul în mâna lui Israel. Iosua l-a cucerit în ziua a doua și l-a trecut prin ascuțișul sabiei, împreună cu fiecare persoană din el, așa cum făcuse Libnei.", "Atunci Horam, regele Ghezerului, a urcat ca să ajute Lachișul, dar Iosua l-a lovit împreună cu poporul lui, fără să-i lase vreun supraviețuitor.", "Iosua a trecut de la Lachiș la Eglon, împreună cu tot Israelul. Și-au așezat tabăra împotriva lui și au luptat împotriva lui.", "În ziua aceea l-au cucerit și l-au trecut prin ascuțișul sabiei. Iosua a dat spre nimicire fiecare persoană din el în ziua aceea, așa cum făcuse Lachișului.", "Iosua a urcat de la Eglon la Hebron, împreună cu tot Israelul, și au luptat împotriva lui.", "L-au cucerit și l-au trecut prin ascuțișul sabiei, împreună cu regele lui, toate cetățile lui și fiecare persoană din ele. Nu a lăsat vreun supraviețuitor, așa cum făcuse Eglonului, ci l-a dat spre nimicire, împreună cu fiecare persoană din el.", "Iosua s-a întors la Debir, împreună cu tot Israelul, și a luptat împotriva lui.", "L-a cucerit împreună cu regele și toate cetățile lui. I-au trecut prin ascuțișul sabiei și au dat spre nimicire fiecare persoană din ele, fără să lase vreun supraviețuitor. Cum făcuse Hebronului, așa a făcut Debirului și regelui lui, cum făcuse și Libnei și regelui ei.", "Iosua a lovit toată țara: regiunea muntoasă, Neghevul, zona deluroasă joasă, versanții și pe toți regii lor. Nu a lăsat vreun supraviețuitor, ci a dat spre nimicire tot ce respira, așa cum poruncise DOMNUL, Dumnezeul lui Israel.", "Iosua i-a lovit de la Cadeș-Barnea până la Gaza și tot ținutul Goșenului până la Gabaon.", "Iosua i-a cucerit pe toți acești regi și țările lor dintr-o singură campanie, pentru că DOMNUL, Dumnezeul lui Israel, lupta pentru Israel.", "Apoi Iosua și tot Israelul împreună cu el s-au întors în tabăra de la Ghilgal."],
    11: ["Când Iabin, regele Hațorului, a auzit aceste lucruri, a trimis soli la Iobab, regele Madonului, la regele Șimronului și la regele Acșafului,", "precum și la regii din nord, din regiunea muntoasă, din Araba, la sud de Chineret, din zona deluroasă joasă și de pe înălțimile Dorului, spre apus;", "la canaaniții de la răsărit și de la apus, la amoriți, hitiți, periziți, iebusiții din regiunea muntoasă și hiviții de sub Hermon, din ținutul Mițpa.", "Ei au ieșit împreună cu toate armatele lor, un popor atât de numeros ca nisipul de pe țărmul mării, cu foarte mulți cai și care.", "Toți acești regi s-au întâlnit, au venit și și-au așezat tabăra împreună la apele Meromului, ca să lupte împotriva lui Israel.", "DOMNUL i-a spus lui Iosua: „Nu te teme de ei, căci mâine, pe vremea aceasta, îi voi da pe toți uciși înaintea lui Israel. Să tai tendoanele cailor lor și să le arzi carele.”", "Iosua a venit pe neașteptate împotriva lor la apele Meromului, împreună cu toți oamenii de război, și i-a atacat.", "DOMNUL i-a dat în mâna lui Israel. Ei i-au lovit și i-au urmărit până la Sidonul cel Mare, până la Misrefot-Maim și până în valea Mițpa, spre răsărit. I-au lovit până când nu le-a mai rămas niciun supraviețuitor.", "Iosua le-a făcut așa cum îi spusese DOMNUL: a tăiat tendoanele cailor lor și le-a ars carele.", "În vremea aceea, Iosua s-a întors, a cucerit Hațorul și l-a lovit cu sabia pe regele lui, căci Hațorul fusese mai înainte căpetenia tuturor acestor regate.", "Au trecut prin ascuțișul sabiei fiecare persoană care se afla în el, dând totul spre nimicire. Nu a rămas nimic care respira, iar Hațorul a fost ars.", "Iosua a cucerit toate cetățile acestor regi și pe toți regii lor. I-a trecut prin ascuțișul sabiei și i-a dat spre nimicire, așa cum poruncise Moise, slujitorul DOMNULUI.", "Dar Israel nu a ars niciuna dintre cetățile care se aflau încă pe movilele lor, în afară de Hațor, pe care Iosua l-a ars.", "Fiii lui Israel au luat pentru ei toată prada acestor cetăți și animalele. Însă pe toți oamenii i-au trecut prin ascuțișul sabiei până i-au nimicit, fără să lase nimic care respira.", "Așa cum DOMNUL îi poruncise lui Moise, slujitorul Său, iar Moise îi poruncise lui Iosua, tot așa a făcut Iosua. Nu a lăsat neîmplinit nimic din tot ce-i poruncise DOMNUL lui Moise.", "Iosua a cucerit astfel toată țara aceea: regiunea muntoasă, tot Neghevul, tot ținutul Goșenului, zona deluroasă joasă, Araba, regiunea muntoasă a lui Israel și zona ei deluroasă joasă,", "de la muntele Halac, care urcă spre Seir, până la Baal-Gad, în valea Libanului, sub muntele Hermon. I-a prins pe toți regii lor, i-a lovit și i-a omorât.", "Iosua a purtat război multă vreme cu toți acești regi.", "Nicio cetate nu a făcut pace cu fiii lui Israel, în afară de hiviții care locuiau în Gabaon. Pe toate celelalte le-au cucerit prin luptă.", "Căci DOMNUL le-a întărit inima, ca să iasă la luptă împotriva lui Israel, pentru ca Israel să-i dea spre nimicire, fără ca ei să primească îndurare, ci să fie nimiciți, așa cum îi poruncise DOMNUL lui Moise.", "În vremea aceea, Iosua a venit și i-a nimicit pe anachimi din regiunea muntoasă: din Hebron, Debir, Anab, din toată regiunea muntoasă a lui Iuda și din toată regiunea muntoasă a lui Israel. Iosua i-a dat spre nimicire împreună cu cetățile lor.", "Nu au mai rămas anachimi în țara fiilor lui Israel; au mai rămas numai în Gaza, Gat și Așdod.", "Astfel, Iosua a cucerit întreaga țară, potrivit cu tot ce-i spusese DOMNUL lui Moise. Iosua a dat-o ca moștenire lui Israel, după împărțirile lor, potrivit semințiilor. Apoi țara a avut odihnă de război."],
    12: ["Aceștia sunt regii țării pe care fiii lui Israel i-au lovit și a căror țară au luat-o în stăpânire dincolo de Iordan, spre răsărit, de la pârâul Arnon până la muntele Hermon, împreună cu toată Araba de la răsărit:", "Sihon, regele amoriților, care locuia la Heșbon și stăpânea de la Aroer, aflat pe marginea văii Arnonului, de la mijlocul văii și peste jumătate din Galaad, până la pârâul Iaboc, hotarul fiilor lui Amon;", "peste Araba până la marea Chineret, spre răsărit, și până la marea Arabei, Marea Sărată, spre răsărit, pe drumul spre Bet-Ieșimot, iar spre sud până sub versanții Pisga;", "și Og, regele Basanului, unul dintre cei rămași dintre refaimi, care locuia la Aștarot și la Edrei.", "El stăpânea peste muntele Hermon, Salca, tot Basanul până la hotarul gheșuriților și maacatiților și peste jumătate din Galaad, până la hotarul lui Sihon, regele Heșbonului.", "Moise, slujitorul DOMNULUI, și fiii lui Israel i-au lovit, iar Moise, slujitorul DOMNULUI, le-a dat țara lor ca moștenire rubeniților, gadiților și jumătății seminției lui Manase.", "Aceștia sunt regii țării pe care Iosua și fiii lui Israel i-au lovit dincolo de Iordan, spre apus, de la Baal-Gad, în valea Libanului, până la muntele Halac, care urcă spre Seir. Iosua a dat țara semințiilor lui Israel ca moștenire, după împărțirile lor:", "în regiunea muntoasă, în zona deluroasă joasă, în Araba, pe versanți, în pustie și în Neghev, țara hitiților, amoriților, canaaniților, periziților, hiviților și iebusiților.", "Regele Ierihonului — unul; regele cetății Ai, de lângă Betel — unul;", "regele Ierusalimului — unul; regele Hebronului — unul;", "regele Iarmutului — unul; regele Lachișului — unul;", "regele Eglonului — unul; regele Ghezerului — unul;", "regele Debirului — unul; regele Ghederului — unul;", "regele Hormei — unul; regele Aradului — unul;", "regele Libnei — unul; regele Adulamului — unul;", "regele Machedei — unul; regele Betelului — unul;", "regele Tapuahului — unul; regele Heferului — unul;", "regele Afecului — unul; regele Lașaronului — unul;", "regele Madonului — unul; regele Hațorului — unul;", "regele Șimron-Meronului — unul; regele Acșafului — unul;", "regele Taanacului — unul; regele Meghidoului — unul;", "regele Chedeșului — unul; regele Iocneamului din Carmel — unul;", "regele Dorului, din ținutul Nafat-Dor — unul; regele Goiimului din Ghilgal — unul;", "regele Tirței — unul. În total, treizeci și unu de regi."],
    13: ["Iosua era bătrân și înaintat în vârstă. DOMNUL i-a spus: „Ai îmbătrânit și ești înaintat în vârstă, iar din țară a rămas încă foarte mult de luat în stăpânire.", "Iată țara care mai rămâne: toate ținuturile filistenilor și tot ținutul gheșuriților,", "de la Șihor, care se află în fața Egiptului, până la hotarul Ecronului, spre nord, teritoriu socotit canaanit; cei cinci conducători ai filistenilor — cel din Gaza, cel din Așdod, cel din Așchelon, cel din Gat și cel din Ecron — precum și aviții,", "spre sud; toată țara canaaniților și Meara, care aparține sidonienilor, până la Afec și până la hotarul amoriților;", "țara ghebaliților și tot Libanul, spre răsărit, de la Baal-Gad, sub muntele Hermon, până la intrarea în Hamat;", "toți locuitorii regiunii muntoase de la Liban până la Misrefot-Maim, adică toți sidonienii. Eu îi voi izgoni dinaintea fiilor lui Israel. Tu doar împarte țara prin sorți lui Israel ca moștenire, așa cum ți-am poruncit.", "Acum împarte țara aceasta ca moștenire celor nouă seminții și jumătății seminției lui Manase.”", "Împreună cu cealaltă jumătate a lui Manase, rubeniții și gadiții își primiseră moștenirea pe care le-o dăduse Moise dincolo de Iordan, spre răsărit, așa cum le-o dăduse Moise, slujitorul DOMNULUI:", "de la Aroer, aflat pe marginea văii Arnonului, și cetatea din mijlocul văii, împreună cu tot podișul Medeba până la Dibon;", "toate cetățile lui Sihon, regele amoriților, care domnea la Heșbon, până la hotarul fiilor lui Amon;", "Galaadul, hotarul gheșuriților și al maacatiților, tot muntele Hermon și tot Basanul până la Salca;", "tot regatul lui Og din Basan, care domnea la Aștarot și la Edrei și era unul dintre cei rămași dintre refaimi. Moise îi lovise și îi izgonise.", "Totuși, fiii lui Israel nu i-au izgonit pe gheșuriți și pe maacatiți; Gheșur și Maaca au locuit în mijlocul lui Israel până în ziua de astăzi.", "Numai seminției lui Levi nu i-a dat nicio moștenire. Darurile aduse prin foc DOMNULUI, Dumnezeul lui Israel, sunt moștenirea ei, așa cum îi spusese.", "Moise a dat o moștenire seminției fiilor lui Ruben, potrivit familiilor lor.", "Hotarul lor pornea de la Aroer, aflat pe marginea văii Arnonului, și de la cetatea din mijlocul văii și cuprindea tot podișul de lângă Medeba;", "Heșbonul și toate cetățile lui din podiș: Dibon, Bamot-Baal, Bet-Baal-Meon,", "Iahaț, Chedemot, Mefaat,", "Chiriataim, Sibma, Țeret-Șahar, pe muntele văii,", "Bet-Peor, versanții Pisga și Bet-Ieșimot;", "toate cetățile podișului și tot regatul lui Sihon, regele amoriților, care domnea la Heșbon. Moise îl lovise pe el și pe conducătorii Midianului — Evi, Rechem, Țur, Hur și Reba — căpeteniile lui Sihon care locuiau în țară.", "Fiii lui Israel l-au omorât cu sabia, printre ceilalți uciși, și pe Balaam, fiul lui Beor, ghicitorul.", "Hotarul fiilor lui Ruben era Iordanul și malul lui. Aceasta a fost moștenirea fiilor lui Ruben, potrivit familiilor lor, cu cetățile și satele lor.", "Moise a dat o moștenire seminției lui Gad, fiilor lui Gad, potrivit familiilor lor.", "Hotarul lor cuprindea Iazerul, toate cetățile Galaadului și jumătate din țara fiilor lui Amon până la Aroer, care este în fața Rabei;", "de la Heșbon până la Ramat-Mițpa și Betonim și de la Mahanaim până la hotarul Debirului;", "iar în vale: Bet-Haram, Bet-Nimra, Sucot și Țafon, restul regatului lui Sihon, regele Heșbonului; Iordanul și malul lui până la capătul mării Chineret, dincolo de Iordan, spre răsărit.", "Aceasta a fost moștenirea fiilor lui Gad, potrivit familiilor lor, cu cetățile și satele lor.", "Moise a dat o moștenire și jumătății seminției lui Manase. Ea a revenit jumătății seminției fiilor lui Manase, potrivit familiilor lor.", "Hotarul lor pornea de la Mahanaim și cuprindea tot Basanul, tot regatul lui Og, regele Basanului, și toate satele lui Iair din Basan — șaizeci de cetăți.", "Jumătate din Galaad, Aștarot și Edrei, cetățile regatului lui Og din Basan, au revenit fiilor lui Machir, fiul lui Manase, adică jumătății fiilor lui Machir, potrivit familiilor lor.", "Acestea sunt moștenirile pe care le-a împărțit Moise în câmpiile Moabului, dincolo de Iordan, la răsărit de Ierihon.", "Dar seminției lui Levi Moise nu i-a dat nicio moștenire. DOMNUL, Dumnezeul lui Israel, este moștenirea ei, așa cum le spusese."],
    14: ["Acestea sunt moștenirile pe care le-au primit fiii lui Israel în țara Canaanului și pe care li le-au împărțit preotul Eleazar, Iosua, fiul lui Nun, și căpeteniile caselor părintești ale semințiilor fiilor lui Israel.", "Moștenirea le-a fost împărțită prin sorți, așa cum poruncise DOMNUL prin Moise, celor nouă seminții și jumătății de seminție.", "Căci Moise dăduse moștenirea celor două seminții și jumătății de seminție dincolo de Iordan, dar leviților nu le dăduse nicio moștenire în mijlocul lor.", "Fiii lui Iosif alcătuiau două seminții: Manase și Efraim. Leviților nu li s-a dat nicio parte în țară, ci numai cetăți în care să locuiască și pășunile din jurul lor pentru turme și bunuri.", "Fiii lui Israel au făcut așa cum îi poruncise DOMNUL lui Moise și au împărțit țara.", "Fiii lui Iuda s-au apropiat de Iosua la Ghilgal, iar Caleb, fiul chenizitului Iefune, i-a spus: „Tu știi ce i-a spus DOMNUL lui Moise, omul lui Dumnezeu, despre mine și despre tine la Cadeș-Barnea.", "Aveam patruzeci de ani când Moise, slujitorul DOMNULUI, m-a trimis din Cadeș-Barnea să cercetez țara. I-am adus un răspuns potrivit convingerii inimii mele.", "Frații mei care urcaseră cu mine au făcut să se topească inima poporului, dar eu L-am urmat pe deplin pe DOMNUL, Dumnezeul meu.", "În ziua aceea, Moise a jurat: «Țara pe care a călcat piciorul tău va fi pentru totdeauna moștenirea ta și a fiilor tăi, pentru că L-ai urmat pe deplin pe DOMNUL, Dumnezeul meu.»", "Acum, iată, DOMNUL m-a ținut în viață, așa cum spusese, în acești patruzeci și cinci de ani de când DOMNUL i-a spus acest cuvânt lui Moise, pe când Israel umbla prin pustie. Iată, astăzi am optzeci și cinci de ani.", "Și astăzi sunt tot atât de puternic ca în ziua când m-a trimis Moise. Cum era puterea mea atunci, așa este puterea mea și acum, pentru război, ca să ies și să intru.", "Acum dă-mi regiunea muntoasă aceasta despre care a vorbit DOMNUL în ziua aceea. Căci ai auzit atunci că acolo se aflau anachimi și cetăți mari și fortificate. Poate că DOMNUL va fi cu mine și îi voi izgoni, așa cum a spus DOMNUL.”", "Iosua l-a binecuvântat și i-a dat Hebronul ca moștenire lui Caleb, fiul lui Iefune.", "De aceea Hebronul a rămas până în ziua de astăzi moștenirea lui Caleb, fiul chenizitului Iefune, pentru că L-a urmat pe deplin pe DOMNUL, Dumnezeul lui Israel.", "Numele Hebronului fusese mai înainte Chiriat-Arba; Arba fusese omul cel mai de seamă dintre anachimi. Apoi țara a avut odihnă de război."],
    15: ["Sorțul pentru seminția fiilor lui Iuda, potrivit familiilor lor, s-a întins până la hotarul Edomului și până la pustia Țin, spre sud, la capătul cel mai îndepărtat al Neghevului.", "Hotarul lor de sud pornea de la capătul Mării Sărate, de la golful care privește spre sud.", "De acolo ieșea la sud de urcușul Acrabim, trecea spre Țin, urca pe la sud de Cadeș-Barnea, trecea prin Hețron, urca spre Adar și se întorcea spre Carca.", "Trecea apoi prin Ațmon, ieșea la pârâul Egiptului, iar capătul hotarului era la mare. Acesta să fie hotarul vostru de sud.", "Hotarul de răsărit era Marea Sărată până la capătul Iordanului. Hotarul laturii de nord pornea de la golful mării, de la capătul Iordanului.", "Hotarul urca spre Bet-Hogla, trecea pe la nord de Bet-Araba și urca până la piatra lui Bohan, fiul lui Ruben.", "Hotarul urca spre Debir din Valea Acorului și se întorcea spre nord, către Ghilgal, aflat în fața urcușului Adumim, la sud de pârâu. Hotarul trecea pe la apele En-Șemeș și se termina la En-Roghel.", "Hotarul urca prin valea fiului lui Hinom până la versantul sudic al cetății iebusiților, adică Ierusalimul, apoi urca până la vârful muntelui aflat la apus de valea lui Hinom, la marginea de nord a văii refaimilor.", "De la vârful muntelui, hotarul se întindea spre izvorul apelor Neftoah, ieșea spre cetățile muntelui Efron și continua spre Baala, adică Chiriat-Iearim.", "De la Baala, hotarul se întorcea spre apus, către muntele Seir, trecea pe la versantul nordic al muntelui Iearim, adică Chesalon, cobora la Bet-Șemeș și trecea prin Timna.", "Hotarul ieșea spre versantul nordic al Ecronului, continua spre Șicheron, trecea pe la muntele Baala, ieșea la Iabneel și se termina la mare.", "Hotarul de apus era țărmul Mării celei Mari. Acesta era hotarul fiilor lui Iuda de jur împrejur, potrivit familiilor lor.", "Lui Caleb, fiul lui Iefune, i s-a dat o parte în mijlocul fiilor lui Iuda, potrivit poruncii DOMNULUI către Iosua: Chiriat-Arba, numit după tatăl lui Anac, adică Hebronul.", "Caleb i-a izgonit de acolo pe cei trei fii ai lui Anac: Șeșai, Ahiman și Talmai, urmașii lui Anac.", "De acolo a urcat împotriva locuitorilor Debirului. Numele Debirului fusese mai înainte Chiriat-Sefer.", "Caleb a spus: „Celui care va lovi Chiriat-Seferul și îl va cuceri îi voi da de soție pe fiica mea Acsa.”", "Otniel, fiul lui Chenaz, fratele lui Caleb, a cucerit cetatea, iar Caleb i-a dat-o de soție pe fiica sa Acsa.", "Când a venit, ea l-a îndemnat pe Otniel să-i ceară tatălui ei un ogor. Apoi a coborât de pe măgar, iar Caleb a întrebat-o: „Ce dorești?”", "Ea a răspuns: „Dă-mi o binecuvântare! Fiindcă mi-ai dat țara Neghevului, dă-mi și izvoare de apă.” Atunci el i-a dat izvoarele de sus și izvoarele de jos.", "Aceasta a fost moștenirea seminției fiilor lui Iuda, potrivit familiilor lor.", "Cetățile de la marginea moștenirii seminției fiilor lui Iuda, spre hotarul Edomului, în Neghev, erau: Cabțeel, Eder, Iagur,", "China, Dimona, Adada,", "Chedeș, Hațor, Itnan,", "Zif, Telem, Bealot,", "Hațor-Hadata, Cheriot-Hețron, adică Hațor,", "Amam, Șema, Molada,", "Hațar-Gada, Heșmon, Bet-Pelet,", "Hațar-Șual, Beer-Șeba, Biziotia,", "Baala, Iim, Ețem,", "Eltolad, Chesil, Horma,", "Țiclag, Madmana, Sansana,", "Lebaot, Șilhim, Ain și Rimon. În total, douăzeci și nouă de cetăți, împreună cu satele lor.", "În zona deluroasă joasă: Eștaol, Țorea, Așna,", "Zanoah, En-Ganim, Tapuah, Enam,", "Iarmut, Adulam, Soco, Azeca,", "Șaaraim, Aditaim, Ghedera și Ghederotaim: paisprezece cetăți, împreună cu satele lor.", "Țenan, Hadașa, Migdal-Gad,", "Dilean, Mițpa, Iocteel,", "Lachiș, Boțcat, Eglon,", "Cabon, Lahmam, Chitliș,", "Ghederot, Bet-Dagon, Naama și Macheda: șaisprezece cetăți, împreună cu satele lor.", "Libna, Eter, Așan,", "Iftah, Așna, Nețib,", "Cheila, Aczib și Mareșa: nouă cetăți, împreună cu satele lor.", "Ecronul, cu cetățile și satele lui;", "de la Ecron până la mare, toate cetățile din apropierea Așdodului, împreună cu satele lor;", "Așdodul, cu cetățile și satele lui; Gaza, cu cetățile și satele ei; până la pârâul Egiptului, Marea cea Mare și țărmul ei.", "În regiunea muntoasă: Șamir, Iatir, Soco,", "Dana, Chiriat-Sana, adică Debir,", "Anab, Eștemo, Anim,", "Goșen, Holon și Ghilo: unsprezece cetăți, împreună cu satele lor.", "Arab, Duma, Eșan,", "Ianim, Bet-Tapuah, Afeca,", "Humta, Chiriat-Arba, adică Hebron, și Țior: nouă cetăți, împreună cu satele lor.", "Maon, Carmel, Zif, Iuta,", "Izreel, Iocdeam, Zanoah,", "Cain, Ghibea și Timna: zece cetăți, împreună cu satele lor.", "Halhul, Bet-Țur, Ghedor,", "Maarat, Bet-Anot și Eltecon: șase cetăți, împreună cu satele lor.", "Chiriat-Baal, adică Chiriat-Iearim, și Raba: două cetăți, împreună cu satele lor.", "În pustie: Bet-Araba, Midin, Secaca,", "Nibșan, Cetatea Sării și En-Ghedi: șase cetăți, împreună cu satele lor.", "Fiii lui Iuda nu au putut să-i izgonească pe iebusiții care locuiau în Ierusalim. Iebusiții au locuit împreună cu fiii lui Iuda la Ierusalim până în ziua de astăzi."],
    16: ["Sorțul fiilor lui Iosif a ieșit de la Iordan, lângă Ierihon, de la apele Ierihonului spre răsărit, prin pustia care urcă de la Ierihon în regiunea muntoasă, spre Betel.", "De la Betel mergea spre Luz și trecea la hotarul archiților, la Atarot.", "Apoi cobora spre apus, la hotarul iafletiților, până la hotarul Bet-Horonului de Jos și până la Ghezer, și se termina la mare.", "Astfel fiii lui Iosif, Manase și Efraim, și-au primit moștenirea.", "Hotarul fiilor lui Efraim, potrivit familiilor lor, era următorul: spre răsărit, hotarul moștenirii lor mergea de la Atarot-Adar până la Bet-Horonul de Sus.", "Hotarul ieșea spre mare, la Micmetat, în partea de nord; apoi se întorcea spre răsărit, către Taanat-Șilo, și trecea pe la răsărit de Ianoah.", "De la Ianoah cobora la Atarot și la Naara, ajungea la Ierihon și ieșea la Iordan.", "De la Tapuah, hotarul mergea spre apus până la pârâul Cana și se termina la mare. Aceasta era moștenirea seminției fiilor lui Efraim, potrivit familiilor lor,", "împreună cu cetățile puse deoparte pentru fiii lui Efraim în mijlocul moștenirii fiilor lui Manase, toate cetățile cu satele lor.", "Ei nu i-au izgonit pe canaaniții care locuiau în Ghezer. Canaaniții au locuit în mijlocul lui Efraim până în ziua de astăzi și au fost supuși la muncă silnică."],
    17: ["Sorțul a ieșit și pentru seminția lui Manase, fiindcă el era întâiul născut al lui Iosif. Lui Machir, întâiul născut al lui Manase și tatăl lui Galaad, i-au revenit Galaadul și Bașanul, pentru că era un om de război.", "Au primit o parte și ceilalți fii ai lui Manase, potrivit familiilor lor: fiii lui Abiezer, fiii lui Helec, fiii lui Asriel, fiii lui Sihem, fiii lui Hefer și fiii lui Șemida. Aceștia erau urmașii de parte bărbătească ai lui Manase, fiul lui Iosif, potrivit familiilor lor.", "Țelofhad, fiul lui Hefer, fiul lui Galaad, fiul lui Machir, fiul lui Manase, nu a avut fii, ci numai fiice. Numele fiicelor lui erau: Mahla, Noa, Hogla, Milca și Tirța.", "Ele s-au înfățișat înaintea preotului Eleazar, înaintea lui Iosua, fiul lui Nun, și înaintea conducătorilor și au spus: „DOMNUL i-a poruncit lui Moise să ne dea o moștenire printre rudele noastre.” Atunci, potrivit poruncii DOMNULUI, Iosua le-a dat o moștenire printre frații tatălui lor.", "Astfel lui Manase i-au revenit zece părți, în afară de țara Galaadului și a Bașanului, aflată dincolo de Iordan,", "pentru că fiicele lui Manase au primit o moștenire printre fiii lui, iar țara Galaadului le-a revenit celorlalți fii ai lui Manase.", "Hotarul lui Manase mergea de la Așer până la Micmetat, aflat în fața Sihemului, apoi continua spre sud, către locuitorii din En-Tapuah.", "Ținutul Tapuahului îi aparținea lui Manase, dar cetatea Tapuah, aflată la hotarul lui Manase, le aparținea fiilor lui Efraim.", "Hotarul cobora la pârâul Cana, pe partea de sud a pârâului. Cetățile acestea ale lui Efraim se aflau în mijlocul cetăților lui Manase. Hotarul lui Manase era pe partea de nord a pârâului și se termina la mare.", "La sud era teritoriul lui Efraim, iar la nord, cel al lui Manase; marea era hotarul lor. Spre nord se învecinau cu Așer, iar spre răsărit, cu Isahar.", "Manase avea în Isahar și în Așer: Bet-Șean și satele lui, Ibleam și satele lui, locuitorii Dorului și satele lui, locuitorii din En-Dor și satele lui, locuitorii din Taanac și satele lui și locuitorii din Meghido și satele lui — cele trei înălțimi.", "Fiii lui Manase nu au putut să-i izgonească pe locuitorii acestor cetăți, iar canaaniții au stăruit să locuiască în ținutul acela.", "Când fiii lui Israel au ajuns puternici, i-au supus pe canaaniți la muncă silnică, dar nu i-au izgonit cu totul.", "Fiii lui Iosif i-au spus lui Iosua: „De ce ne-ai dat ca moștenire numai un sorț și o singură parte, deși suntem un popor numeros, fiindcă DOMNUL ne-a binecuvântat până acum?”", "Iosua le-a răspuns: „Dacă sunteți un popor numeros și regiunea muntoasă a lui Efraim este prea strâmtă pentru voi, urcați în pădure și curățați-vă acolo un loc în țara fereziților și a refaimilor.”", "Fiii lui Iosif au spus: „Regiunea muntoasă nu ne este de ajuns, iar toți canaaniții care locuiesc în ținutul văii au care de fier: atât cei din Bet-Șean și din satele lui, cât și cei din valea Izreel.”", "Iosua i-a spus casei lui Iosif, adică lui Efraim și lui Manase: „Sunteți un popor numeros și aveți o mare putere. Nu veți avea numai un singur sorț,", "ci regiunea muntoasă va fi a voastră. Chiar dacă este împădurită, o veți curăța, iar hotarele ei îndepărtate vor fi ale voastre. Îi veți izgoni pe canaaniți, deși au care de fier și sunt puternici.”"],
    18: ["Toată adunarea fiilor lui Israel s-a strâns la Șilo și a așezat acolo Cortul Întâlnirii. Țara era supusă înaintea lor.", "Mai rămâneau printre fiii lui Israel șapte seminții care nu-și împărțiseră încă moștenirea.", "Iosua le-a spus fiilor lui Israel: „Până când veți întârzia să mergeți și să luați în stăpânire țara pe care v-a dat-o DOMNUL, Dumnezeul părinților voștri?", "Alegeți câte trei bărbați din fiecare seminție. Îi voi trimite, iar ei se vor ridica, vor străbate țara și o vor descrie potrivit moștenirilor ei, apoi se vor întoarce la mine.", "S-o împartă în șapte părți. Iuda să rămână în hotarul său la sud, iar casa lui Iosif să rămână în hotarul ei la nord.", "Voi să descrieți țara în șapte părți și să-mi aduceți descrierea aici. Atunci voi arunca sorții pentru voi aici, înaintea DOMNULUI, Dumnezeul nostru.", "Leviții nu au parte în mijlocul vostru, fiindcă preoția DOMNULUI este moștenirea lor. Gad, Ruben și jumătatea seminției lui Manase și-au primit moștenirea dincolo de Iordan, spre răsărit, moștenire pe care le-a dat-o Moise, slujitorul DOMNULUI.”", "Bărbații s-au ridicat și au plecat. Iosua le-a poruncit celor care mergeau să descrie țara: „Mergeți, străbateți țara, descrieți-o și întoarceți-vă la mine. Voi arunca sorții pentru voi aici, înaintea DOMNULUI, la Șilo.”", "Bărbații au mers, au străbătut țara și au descris-o, cetate cu cetate, în șapte părți, într-o carte. Apoi s-au întors la Iosua, în tabăra de la Șilo.", "Iosua a aruncat sorții pentru ei la Șilo, înaintea DOMNULUI. Acolo Iosua a împărțit țara fiilor lui Israel, potrivit împărțirilor lor.", "Sorțul seminției fiilor lui Beniamin a ieșit potrivit familiilor lor. Hotarul părții lor a trecut între fiii lui Iuda și fiii lui Iosif.", "Hotarul lor dinspre nord pornea de la Iordan, urca pe latura nordică a Ierihonului, urca prin regiunea muntoasă spre apus și se termina în pustia Bet-Aven.", "De acolo hotarul trecea spre Luz, pe latura sudică a Luzului, adică Betel, apoi cobora la Atarot-Adar, lângă muntele aflat la sud de Bet-Horonul de Jos.", "Hotarul se întorcea și cotea pe partea de apus spre sud, de la muntele aflat în fața Bet-Horonului, spre sud, și se termina la Chiriat-Baal, adică Chiriat-Iearim, cetate a fiilor lui Iuda. Aceasta era latura de apus.", "Latura de sud pornea de la marginea Chiriat-Iearimului. Hotarul ieșea spre apus și ajungea la izvorul apelor Neftoah.", "Hotarul cobora la marginea muntelui aflat în fața văii fiului lui Hinom, în partea de nord a văii refaimilor. Apoi cobora prin valea lui Hinom, pe latura sudică a cetății iebusiților, și cobora la En-Roghel.", "De acolo se întorcea spre nord, ieșea la En-Șemeș, continua spre Ghelilot, aflat în fața urcușului Adumim, și cobora la piatra lui Bohan, fiul lui Ruben.", "Trecea apoi pe lângă versantul aflat în fața Arabei, spre nord, și cobora în Araba.", "Hotarul trecea pe latura nordică a Bet-Hoglei și se termina la golful nordic al Mării Sărate, la capătul sudic al Iordanului. Acesta era hotarul de sud.", "Iordanul era hotarul de răsărit. Aceasta era moștenirea fiilor lui Beniamin, după hotarele ei de jur împrejur, potrivit familiilor lor.", "Cetățile seminției fiilor lui Beniamin, potrivit familiilor lor, erau: Ierihon, Bet-Hogla, Emec-Chețiț,", "Bet-Araba, Țemaraim, Betel,", "Avim, Para, Ofra,", "Chefar-Amoni, Ofni și Gheba: douăsprezece cetăți, împreună cu satele lor.", "Gabaon, Rama, Beerot,", "Mițpe, Chefira, Moța,", "Rechem, Irpeel, Tarala,", "Țela, Elef, cetatea iebusiților, adică Ierusalimul, Ghibeat și Chiriat: paisprezece cetăți, împreună cu satele lor. Aceasta era moștenirea fiilor lui Beniamin, potrivit familiilor lor."],
    19: ["Al doilea sorț a ieșit pentru Simeon, pentru seminția fiilor lui Simeon, potrivit familiilor lor. Moștenirea lor se afla în mijlocul moștenirii fiilor lui Iuda.", "În moștenirea lor se aflau Beer-Șeba, sau Șeba, Molada,", "Hațar-Șual, Bala, Ețem,", "Eltolad, Betul, Horma,", "Țiclag, Bet-Marcabot, Hațar-Susa,", "Bet-Lebaot și Șaruhen: treisprezece cetăți, împreună cu satele lor;", "Ain, Rimon, Eter și Așan: patru cetăți, împreună cu satele lor;", "și toate satele din jurul acestor cetăți până la Baalat-Beer, Rama din Neghev. Aceasta era moștenirea seminției fiilor lui Simeon, potrivit familiilor lor.", "Moștenirea fiilor lui Simeon a fost luată din partea fiilor lui Iuda, fiindcă partea fiilor lui Iuda era prea mare pentru ei. De aceea fiii lui Simeon și-au primit moștenirea în mijlocul moștenirii lor.", "Al treilea sorț a ieșit pentru fiii lui Zabulon, potrivit familiilor lor. Hotarul moștenirii lor ajungea până la Sarid.", "Hotarul lor urca spre apus, la Marala, ajungea la Dabeșet și apoi la pârâul aflat în fața Iocneamului.", "De la Sarid se întorcea spre răsărit, către răsăritul soarelui, până la hotarul Chislot-Taborului, ieșea la Daberat și urca la Iafia.", "De acolo trecea spre răsărit, către răsăritul soarelui, la Gat-Hefer și Et-Cațin, apoi ieșea la Rimon și se întindea până la Nea.", "Hotarul se întorcea în jurul lui, spre nord, la Hanaton și se termina în valea Iftah-El.", "Mai erau Catat, Nahalal, Șimron, Idala și Betleem: douăsprezece cetăți, împreună cu satele lor.", "Aceasta era moștenirea fiilor lui Zabulon, potrivit familiilor lor: cetățile acestea cu satele lor.", "Al patrulea sorț a ieșit pentru Isahar, pentru fiii lui Isahar, potrivit familiilor lor.", "Hotarul lor cuprindea Izreel, Chesulot, Șunem,", "Hafaraim, Șion, Anaharat,", "Rabit, Chișion, Ebeț,", "Remet, En-Ganim, En-Hada și Bet-Pațeț.", "Hotarul ajungea la Tabor, Șahațuma și Bet-Șemeș și se termina la Iordan: șaisprezece cetăți, împreună cu satele lor.", "Aceasta era moștenirea seminției fiilor lui Isahar, potrivit familiilor lor: cetățile cu satele lor.", "Al cincilea sorț a ieșit pentru seminția fiilor lui Așer, potrivit familiilor lor.", "Hotarul lor cuprindea Helcat, Hali, Beten, Acșaf,", "Alamelec, Amad și Mișal. Ajungea spre apus la Carmel și la Șihor-Libnat.", "Apoi se întorcea spre răsărit la Bet-Dagon, ajungea la Zabulon și la valea Iftah-El, spre nord, la Bet-Emec și Neiel, și ieșea la Cabul, spre nord.", "Apoi mergea la Ebron, Rehob, Hamon și Cana, până la Sidonul cel Mare.", "Hotarul se întorcea spre Rama și spre cetatea fortificată Tir; apoi se întorcea spre Hosa și se termina la mare, în regiunea Aczib.", "Mai erau Uma, Afec și Rehob: douăzeci și două de cetăți, împreună cu satele lor.", "Aceasta era moștenirea seminției fiilor lui Așer, potrivit familiilor lor: cetățile acestea cu satele lor.", "Al șaselea sorț a ieșit pentru fiii lui Neftali, pentru fiii lui Neftali, potrivit familiilor lor.", "Hotarul lor pornea de la Helef, de la stejarul din Țaananim, trecea prin Adami-Necheb și Iabneel până la Lacum și se termina la Iordan.", "Hotarul se întorcea spre apus la Aznot-Tabor și ieșea de acolo la Hucoc. Ajungea la Zabulon în sud, la Așer în apus și la Iuda, lângă Iordan, spre răsărit.", "Cetățile fortificate erau: Țidim, Țer, Hamat, Racat, Chineret,", "Adama, Rama, Hațor,", "Chedeș, Edrei, En-Hațor,", "Iron, Migdal-El, Horem, Bet-Anat și Bet-Șemeș: nouăsprezece cetăți, împreună cu satele lor.", "Aceasta era moștenirea seminției fiilor lui Neftali, potrivit familiilor lor: cetățile cu satele lor.", "Al șaptelea sorț a ieșit pentru seminția fiilor lui Dan, potrivit familiilor lor.", "Hotarul moștenirii lor cuprindea Țorea, Eștaol, Ir-Șemeș,", "Șaalabin, Aialon, Itla,", "Elon, Timna, Ecron,", "Elteche, Ghibeton, Baalat,", "Iehud, Bene-Berac, Gat-Rimon,", "Me-Iarcon și Racon, împreună cu hotarul din fața Iafo.", "Hotarul fiilor lui Dan se întindea dincolo de ei. De aceea fiii lui Dan au urcat și au luptat împotriva Leșemului, l-au cucerit, l-au trecut prin ascuțișul sabiei, l-au luat în stăpânire și au locuit în el. Au numit Leșemul Dan, după numele tatălui lor Dan.", "Aceasta era moștenirea seminției fiilor lui Dan, potrivit familiilor lor: cetățile acestea cu satele lor.", "După ce au terminat de împărțit țara ca moștenire, potrivit hotarelor ei, fiii lui Israel i-au dat și lui Iosua, fiul lui Nun, o moștenire în mijlocul lor.", "Potrivit poruncii DOMNULUI, i-au dat cetatea pe care a cerut-o, Timnat-Serah, în regiunea muntoasă a lui Efraim. El a reconstruit cetatea și a locuit în ea.", "Acestea sunt moștenirile pe care preotul Eleazar, Iosua, fiul lui Nun, și căpeteniile familiilor semințiilor fiilor lui Israel le-au împărțit prin sorți la Șilo, înaintea DOMNULUI, la intrarea Cortului Întâlnirii. Astfel au terminat de împărțit țara."],
    20: ["DOMNUL i-a vorbit lui Iosua și i-a spus:", "„Vorbește-le fiilor lui Israel și spune-le: «Puneți deoparte cetățile de refugiu despre care v-am vorbit prin Moise,", "pentru ca acolo să poată fugi cel care ucide o persoană din greșeală, fără intenție. Ele să vă fie loc de refugiu dinaintea răzbunătorului sângelui.", "Cel care fuge într-una dintre aceste cetăți să stea la intrarea porții cetății și să-și prezinte cazul înaintea bătrânilor acelei cetăți. Ei să-l primească la ei în cetate și să-i dea un loc unde să locuiască printre ei.", "Dacă răzbunătorul sângelui îl urmărește, ei să nu-l dea pe cel care a ucis în mâna lui, fiindcă și-a lovit semenul fără intenție și nu-l ura mai înainte.", "El să locuiască în cetatea aceea până când se va înfățișa înaintea adunării pentru judecată și până la moartea marelui-preot care va fi în slujbă în zilele acelea. După aceea, cel care a ucis se va putea întoarce în cetatea și în casa sa, în cetatea din care fugise.»”", "Au pus deoparte Chedeșul în Galileea, în regiunea muntoasă a lui Neftali, Sihemul în regiunea muntoasă a lui Efraim și Chiriat-Arba, adică Hebronul, în regiunea muntoasă a lui Iuda.", "Dincolo de Iordan, la răsărit de Ierihon, au ales Bețerul în pustie, pe podiș, din seminția lui Ruben, Ramotul din Galaad, din seminția lui Gad, și Golanul din Bașan, din seminția lui Manase.", "Acestea au fost cetățile rânduite pentru toți fiii lui Israel și pentru străinul care locuia printre ei, pentru ca oricine ucidea o persoană fără intenție să poată fugi acolo și să nu moară de mâna răzbunătorului sângelui înainte de a se înfățișa înaintea adunării."],
    21: ["Căpeteniile familiilor părintești ale leviților s-au apropiat de preotul Eleazar, de Iosua, fiul lui Nun, și de căpeteniile familiilor părintești ale semințiilor fiilor lui Israel.", "Le-au vorbit la Șilo, în țara Canaanului, și au spus: „DOMNUL a poruncit prin Moise să ni se dea cetăți în care să locuim și terenuri de pășunat în jurul lor pentru vitele noastre.”", "Atunci fiii lui Israel le-au dat leviților, din moștenirea lor, următoarele cetăți cu terenurile lor de pășunat, potrivit poruncii DOMNULUI.", "Sorțul a ieșit pentru familiile chehatiților. Fiii preotului Aaron, dintre leviți, au primit prin sorți treisprezece cetăți din seminția lui Iuda, din seminția lui Simeon și din seminția lui Beniamin.", "Ceilalți fii ai lui Chehat au primit prin sorți zece cetăți din familiile seminției lui Efraim, din seminția lui Dan și din jumătatea seminției lui Manase.", "Fiii lui Gherșon au primit prin sorți treisprezece cetăți din familiile seminției lui Isahar, din seminția lui Așer, din seminția lui Neftali și din jumătatea seminției lui Manase din Bașan.", "Fiii lui Merari, potrivit familiilor lor, au primit douăsprezece cetăți din seminția lui Ruben, din seminția lui Gad și din seminția lui Zabulon.", "Fiii lui Israel le-au dat leviților prin sorți aceste cetăți cu terenurile lor de pășunat, așa cum poruncise DOMNUL prin Moise.", "Din seminția fiilor lui Iuda și din seminția fiilor lui Simeon au dat următoarele cetăți, menționate pe nume.", "Ele le-au revenit fiilor lui Aaron, dintre familiile chehatiților, dintre fiii lui Levi, pentru că primul sorț a fost al lor.", "Le-au dat Chiriat-Arba, numită după tatăl lui Anac, adică Hebronul, în regiunea muntoasă a lui Iuda, împreună cu terenurile de pășunat din jurul ei.", "Dar câmpurile cetății și satele ei i le-au dat lui Caleb, fiul lui Iefune, ca proprietate.", "Fiilor preotului Aaron le-au dat Hebronul, cetatea de refugiu pentru cel care ucide, cu terenurile de pășunat din jur, și Libna cu terenurile ei de pășunat;", "Iatir cu terenurile lui de pășunat, Eștemoa cu terenurile ei de pășunat,", "Holon cu terenurile lui de pășunat, Debir cu terenurile lui de pășunat,", "Ain cu terenurile lui de pășunat, Iuta cu terenurile ei de pășunat și Bet-Șemeș cu terenurile lui de pășunat: nouă cetăți din aceste două seminții.", "Din seminția lui Beniamin le-au dat Gabaonul cu terenurile lui de pășunat și Gheba cu terenurile ei de pășunat,", "Anatotul cu terenurile lui de pășunat și Almonul cu terenurile lui de pășunat: patru cetăți.", "Toate cetățile fiilor lui Aaron, preoții, au fost treisprezece cetăți cu terenurile lor de pășunat.", "Familiile celorlalți fii ai lui Chehat, dintre leviți, au primit prin sorți cetăți din seminția lui Efraim.", "Le-au dat Sihemul, cetatea de refugiu pentru cel care ucide, cu terenurile de pășunat din jur, în regiunea muntoasă a lui Efraim, și Ghezerul cu terenurile lui de pășunat,", "Chibțaimul cu terenurile lui de pășunat și Bet-Horonul cu terenurile lui de pășunat: patru cetăți.", "Din seminția lui Dan le-au dat Elteche cu terenurile ei de pășunat și Ghibetonul cu terenurile lui de pășunat,", "Aialonul cu terenurile lui de pășunat și Gat-Rimonul cu terenurile lui de pășunat: patru cetăți.", "Din jumătatea seminției lui Manase le-au dat Taanacul cu terenurile lui de pășunat și Gat-Rimonul cu terenurile lui de pășunat: două cetăți.", "Toate cetățile familiilor celorlalți fii ai lui Chehat au fost zece, cu terenurile lor de pășunat.", "Fiilor lui Gherșon, dintre familiile leviților, le-au dat din jumătatea seminției lui Manase Golanul din Bașan, cetatea de refugiu pentru cel care ucide, cu terenurile lui de pășunat, și Be-Eștera cu terenurile ei de pășunat: două cetăți.", "Din seminția lui Isahar le-au dat Chișionul cu terenurile lui de pășunat și Dabratul cu terenurile lui de pășunat,", "Iarmutul cu terenurile lui de pășunat și En-Ganimul cu terenurile lui de pășunat: patru cetăți.", "Din seminția lui Așer le-au dat Mișalul cu terenurile lui de pășunat și Abdonul cu terenurile lui de pășunat,", "Helcatul cu terenurile lui de pășunat și Rehobul cu terenurile lui de pășunat: patru cetăți.", "Din seminția lui Neftali le-au dat Chedeșul din Galileea, cetatea de refugiu pentru cel care ucide, cu terenurile lui de pășunat, Hamot-Dorul cu terenurile lui de pășunat și Cartanul cu terenurile lui de pășunat: trei cetăți.", "Toate cetățile gherșoniților, potrivit familiilor lor, au fost treisprezece cetăți cu terenurile lor de pășunat.", "Familiilor fiilor lui Merari, ceilalți leviți, le-au dat din seminția lui Zabulon Iocneamul cu terenurile lui de pășunat și Carta cu terenurile ei de pășunat,", "Dimna cu terenurile ei de pășunat și Nahalalul cu terenurile lui de pășunat: patru cetăți.", "Din seminția lui Ruben le-au dat Bețerul cu terenurile lui de pășunat și Iahațul cu terenurile lui de pășunat,", "Chedemotul cu terenurile lui de pășunat și Mefaatul cu terenurile lui de pășunat: patru cetăți.", "Din seminția lui Gad le-au dat Ramotul din Galaad, cetatea de refugiu pentru cel care ucide, cu terenurile lui de pășunat, și Mahanaimul cu terenurile lui de pășunat,", "Heșbonul cu terenurile lui de pășunat și Iazerul cu terenurile lui de pășunat: în total patru cetăți.", "Toate acestea au fost cetățile fiilor lui Merari, potrivit familiilor lor, adică ale celorlalte familii ale leviților. Sorțul lor a fost de douăsprezece cetăți.", "Toate cetățile leviților din mijlocul proprietății fiilor lui Israel au fost patruzeci și opt de cetăți cu terenurile lor de pășunat.", "Fiecare dintre aceste cetăți avea terenuri de pășunat în jurul ei. Așa era cu toate cetățile acestea.", "DOMNUL i-a dat lui Israel toată țara pe care jurase că o va da părinților lor. Ei au luat-o în stăpânire și au locuit în ea.", "DOMNUL le-a dat odihnă de jur împrejur, potrivit cu tot ce jurase părinților lor. Niciunul dintre dușmanii lor nu le-a putut sta împotrivă; DOMNUL i-a dat pe toți dușmanii lor în mâna lor.", "Niciunul dintre toate lucrurile bune pe care DOMNUL le spusese casei lui Israel nu a rămas neîmplinit. Toate s-au împlinit."],
    22: ["Atunci Iosua i-a chemat pe rubeniți, pe gadiți și jumătatea seminției lui Manase.", "și le-a spus: „Ați păzit tot ce v-a poruncit Moise, slujitorul DOMNULUI, și ați ascultat de glasul meu în tot ce v-am poruncit.", "Nu i-ați părăsit pe frații voștri în toate aceste zile, până astăzi, ci ați împlinit îndatorirea poruncii DOMNULUI, Dumnezeul vostru.", "Acum, DOMNUL, Dumnezeul vostru, le-a dat odihnă fraților voștri, așa cum le spusese. Întoarceți-vă deci la corturile voastre, în țara moștenirii voastre, pe care v-a dat-o Moise, slujitorul DOMNULUI, dincolo de Iordan.", "Numai să aveți mare grijă să împliniți porunca și Legea pe care v-a dat-o Moise, slujitorul DOMNULUI: să-L iubiți pe DOMNUL, Dumnezeul vostru, să umblați în toate căile Lui, să păziți poruncile Lui, să vă alipiți de El și să-I slujiți din toată inima și din tot sufletul vostru.”", "Iosua i-a binecuvântat și le-a dat drumul, iar ei s-au dus la corturile lor.", "Uneia dintre jumătățile seminției lui Manase, Moise îi dăduse moștenirea în Bașan, iar celeilalte jumătăți Iosua îi dăduse moștenirea împreună cu frații ei, la apus de Iordan. Când Iosua le-a dat drumul la corturile lor, i-a binecuvântat.", "și le-a spus: „Întoarceți-vă la corturile voastre cu multe bogății, cu foarte multe vite, cu argint, aur, bronz, fier și foarte multe haine. Împărțiți cu frații voștri prada luată de la dușmani.”", "Fiii lui Ruben, fiii lui Gad și jumătatea seminției lui Manase s-au întors și au plecat de la fiii lui Israel, din Șilo, care este în țara Canaanului, ca să meargă în țara Galaadului, țara moștenirii lor, pe care o primiseră potrivit poruncii DOMNULUI prin Moise.", "Când au ajuns în ținuturile Iordanului, în țara Canaanului, fiii lui Ruben, fiii lui Gad și jumătatea seminției lui Manase au construit acolo, lângă Iordan, un altar mare și impunător.", "Fiii lui Israel au auzit spunându-se: „Iată, fiii lui Ruben, fiii lui Gad și jumătatea seminției lui Manase au construit un altar la hotarul țării Canaanului, în ținutul Iordanului, pe partea fiilor lui Israel.”", "Când fiii lui Israel au auzit lucrul acesta, întreaga adunare a fiilor lui Israel s-a strâns la Șilo ca să urce împotriva lor la război.", "Fiii lui Israel l-au trimis la fiii lui Ruben, la fiii lui Gad și la jumătatea seminției lui Manase, în țara Galaadului, pe Fineas, fiul preotului Eleazar.", "Împreună cu el au trimis zece căpetenii, câte o căpetenie a unei familii părintești din fiecare seminție a lui Israel. Fiecare era capul familiei sale părintești între miile lui Israel.", "Ei au venit la fiii lui Ruben, la fiii lui Gad și la jumătatea seminției lui Manase, în țara Galaadului, și le-au spus:", "„Așa vorbește întreaga adunare a DOMNULUI: «Ce necredincioșie este aceasta pe care ați săvârșit-o împotriva Dumnezeului lui Israel, întorcându-vă astăzi de la urmarea DOMNULUI și construindu-vă un altar, ca să vă răzvrătiți astăzi împotriva DOMNULUI?", "Nu ne este de ajuns vina de la Peor, de care nu ne-am curățit până în ziua aceasta, deși urgia a venit peste adunarea DOMNULUI?", "Voi vă întoarceți astăzi de la urmarea DOMNULUI! Dacă vă răzvrătiți astăzi împotriva DOMNULUI, mâine El Se va mânia pe întreaga adunare a lui Israel.", "Dacă țara moștenirii voastre este necurată, treceți în țara moștenirii DOMNULUI, unde locuiește Cortul DOMNULUI, și luați-vă moștenire printre noi. Dar nu vă răzvrătiți împotriva DOMNULUI și nici împotriva noastră, construindu-vă un altar în afară de altarul DOMNULUI, Dumnezeul nostru.", "Oare Acan, fiul lui Zerah, nu a săvârșit o necredincioșie cu lucrul dat spre nimicire, iar mânia a căzut peste întreaga adunare a lui Israel? El nu a pierit singur pentru vina lui.»”", "Atunci fiii lui Ruben, fiii lui Gad și jumătatea seminției lui Manase au răspuns și le-au vorbit căpeteniilor miilor lui Israel:", "„Cel Puternic, Dumnezeu, DOMNUL! Cel Puternic, Dumnezeu, DOMNUL! El știe, iar Israel să știe: dacă am făcut aceasta din răzvrătire sau din necredincioșie față de DOMNUL, să nu ne cruțe astăzi!", "Dacă ne-am construit altarul ca să ne întoarcem de la urmarea DOMNULUI, ca să aducem pe el arderi-de-tot, daruri de mâncare sau jertfe de pace, DOMNUL Însuși să ne ceară socoteală.", "Dar am făcut lucrul acesta din teamă, pentru un motiv anume. Ne-am spus: «În viitor, copiii voștri ar putea să le spună copiilor noștri: ‘Ce legătură aveți voi cu DOMNUL, Dumnezeul lui Israel?", "DOMNUL a pus Iordanul ca hotar între noi și voi, fiii lui Ruben și fiii lui Gad. Voi nu aveți parte în DOMNUL.’ Astfel, copiii voștri i-ar putea face pe copiii noștri să nu se mai teamă de DOMNUL.»", "De aceea ne-am spus: «Să ne pregătim să construim un altar, nu pentru arderi-de-tot și nici pentru jertfe,", "ci ca să fie martor între noi și voi și între generațiile noastre după noi, că vom împlini slujirea DOMNULUI înaintea Lui prin arderile-de-tot, jertfele și jertfele noastre de pace. Astfel, copiii voștri nu le vor putea spune în viitor copiilor noștri: ‘Nu aveți parte în DOMNUL.’»", "Ne-am mai spus: «Dacă ne vor vorbi astfel nouă sau generațiilor noastre în viitor, vom spune: ‘Priviți copia altarului DOMNULUI, pe care au făcut-o părinții noștri, nu pentru arderi-de-tot și nici pentru jertfe, ci ca martor între noi și voi.’»", "Departe de noi să ne răzvrătim împotriva DOMNULUI și să ne întoarcem astăzi de la urmarea DOMNULUI, construind un altar pentru arderi-de-tot, daruri de mâncare sau jertfe, în afară de altarul DOMNULUI, Dumnezeul nostru, care este înaintea Cortului Său!”", "Când preotul Fineas, căpeteniile adunării și capii miilor lui Israel care erau cu el au auzit cuvintele fiilor lui Ruben, ale fiilor lui Gad și ale fiilor lui Manase, au fost mulțumiți.", "Fineas, fiul preotului Eleazar, le-a spus fiilor lui Ruben, fiilor lui Gad și fiilor lui Manase: „Astăzi știm că DOMNUL este în mijlocul nostru, pentru că nu ați săvârșit această necredincioșie împotriva DOMNULUI. Acum i-ați scăpat pe fiii lui Israel din mâna DOMNULUI.”", "Fineas, fiul preotului Eleazar, și căpeteniile s-au întors de la fiii lui Ruben și de la fiii lui Gad, din țara Galaadului în țara Canaanului, la fiii lui Israel, și le-au adus răspunsul.", "Lucrul acesta le-a plăcut fiilor lui Israel. Fiii lui Israel L-au binecuvântat pe Dumnezeu și nu au mai vorbit să urce împotriva lor la război ca să distrugă țara în care locuiau fiii lui Ruben și fiii lui Gad.", "Fiii lui Ruben și fiii lui Gad au numit altarul „Martor”, căci au spus: „El este martor între noi că DOMNUL este Dumnezeu.”"],
    23: ["După multe zile, după ce DOMNUL îi dăduse lui Israel odihnă de toți dușmanii din jur, iar Iosua îmbătrânise și era înaintat în vârstă,", "Iosua a chemat tot Israelul, pe bătrânii lui, pe căpeteniile lui, pe judecătorii lui și pe supraveghetorii lui, și le-a spus: „Eu am îmbătrânit și sunt înaintat în vârstă.", "Voi ați văzut tot ce a făcut DOMNUL, Dumnezeul vostru, tuturor acestor națiuni din cauza voastră, căci DOMNUL, Dumnezeul vostru, este Cel care a luptat pentru voi.", "Iată, v-am împărțit prin sorți ca moștenire pentru semințiile voastre aceste națiuni care au rămas, de la Iordan până la Marea cea Mare, spre apus, împreună cu toate națiunile pe care le-am nimicit.", "DOMNUL, Dumnezeul vostru, le va alunga dinaintea voastră și le va izgoni din fața voastră, iar voi le veți lua țara în stăpânire, așa cum v-a spus DOMNUL, Dumnezeul vostru.", "Fiți deci foarte tari ca să păziți și să împliniți tot ce este scris în Cartea Legii lui Moise, fără să vă abateți de la ea nici la dreapta, nici la stânga.", "Să nu vă amestecați cu aceste națiuni care au rămas printre voi. Să nu pomeniți numele dumnezeilor lor, să nu puneți pe nimeni să jure pe ei, să nu le slujiți și să nu vă plecați înaintea lor.", "Ci alipiți-vă de DOMNUL, Dumnezeul vostru, așa cum ați făcut până în ziua aceasta.", "DOMNUL a izgonit dinaintea voastră națiuni mari și puternice, iar înaintea voastră nimeni nu a putut sta până în ziua aceasta.", "Un singur om dintre voi va urmări o mie, pentru că DOMNUL, Dumnezeul vostru, este Cel care luptă pentru voi, așa cum v-a spus.", "Vegheați cu mare grijă asupra sufletelor voastre, ca să-L iubiți pe DOMNUL, Dumnezeul vostru.", "Dar dacă vă întoarceți și vă alipiți de rămășița acestor națiuni care au rămas printre voi, dacă vă înrudiți cu ele prin căsătorie și intrați în legături cu ele, iar ele cu voi,", "să știți sigur că DOMNUL, Dumnezeul vostru, nu va mai izgoni aceste națiuni dinaintea voastră. Ele vor fi pentru voi o cursă și un laț, un bici pe coaste și spini în ochi, până când veți pieri din această țară bună pe care v-a dat-o DOMNUL, Dumnezeul vostru.", "Iată, astăzi merg pe calea întregului pământ. Voi știți din toată inima și din tot sufletul vostru că niciunul dintre toate lucrurile bune pe care vi le-a spus DOMNUL, Dumnezeul vostru, nu a rămas neîmplinit. Toate s-au împlinit pentru voi; niciunul nu a rămas neîmplinit.", "Dar, după cum au venit peste voi toate lucrurile bune pe care vi le-a spus DOMNUL, Dumnezeul vostru, tot așa DOMNUL va aduce peste voi toate lucrurile rele, până când vă va nimici din această țară bună pe care v-a dat-o DOMNUL, Dumnezeul vostru.", "Dacă încălcați legământul DOMNULUI, Dumnezeul vostru, pe care vi l-a poruncit, și mergeți să slujiți altor dumnezei și să vă plecați înaintea lor, mânia DOMNULUI se va aprinde împotriva voastră și veți pieri repede din țara bună pe care v-a dat-o.”"],
    24: ["Iosua a adunat toate semințiile lui Israel la Sihem. I-a chemat pe bătrânii lui Israel, pe căpeteniile lui, pe judecătorii lui și pe supraveghetorii lui, iar ei s-au înfățișat înaintea lui Dumnezeu.", "Iosua a spus întregului popor: „Așa vorbește DOMNUL, Dumnezeul lui Israel: «În vechime, părinții voștri locuiau dincolo de Râu: Terah, tatăl lui Avraam și al lui Nahor. Ei slujeau altor dumnezei.", "Eu l-am luat pe tatăl vostru Avraam de dincolo de Râu, l-am condus prin toată țara Canaanului, i-am înmulțit urmașii și i l-am dat pe Isaac.", "Lui Isaac i i-am dat pe Iacov și pe Esau. Lui Esau i-am dat muntele Seir ca să-l stăpânească, iar Iacov și fiii lui au coborât în Egipt.", "Apoi i-am trimis pe Moise și pe Aaron și am lovit Egiptul prin ceea ce am făcut în mijlocul lui. După aceea v-am scos de acolo.", "I-am scos pe părinții voștri din Egipt și ați ajuns la mare. Egiptenii i-au urmărit pe părinții voștri cu care și călăreți până la Marea Roșie.", "Ei au strigat către DOMNUL, iar El a pus întuneric între voi și egipteni, a adus marea peste ei și i-a acoperit. Ochii voștri au văzut ce am făcut în Egipt. Apoi ați locuit multe zile în pustiu.", "V-am adus în țara amoriților care locuiau dincolo de Iordan. Ei au luptat împotriva voastră, dar Eu i-am dat în mâna voastră. Le-ați luat țara în stăpânire, iar Eu i-am nimicit dinaintea voastră.", "Balac, fiul lui Țipor, regele Moabului, s-a ridicat și a luptat împotriva lui Israel. El a trimis să-l cheme pe Balaam, fiul lui Beor, ca să vă blesteme.", "Dar Eu nu am vrut să-l ascult pe Balaam, așa că el v-a binecuvântat. Astfel v-am scăpat din mâna lui.", "Ați trecut Iordanul și ați ajuns la Ierihon. Oamenii Ierihonului au luptat împotriva voastră, precum și amoriții, periziții, canaaniții, hetiții, ghirgasiții, heviții și iebusiții, dar Eu i-am dat în mâna voastră.", "Am trimis înaintea voastră viespea, care i-a alungat dinaintea voastră, pe cei doi regi ai amoriților. Nu sabia și nu arcul vostru au făcut aceasta.", "V-am dat o țară pentru care nu ați muncit și cetăți pe care nu voi le-ați construit, iar voi locuiți în ele. Mâncați din vii și din livezi de măslini pe care nu voi le-ați plantat.»", "Acum, temeți-vă de DOMNUL și slujiți-I cu integritate și credincioșie. Îndepărtați dumnezeii cărora le-au slujit părinții voștri dincolo de Râu și în Egipt și slujiți-I DOMNULUI.", "Dacă vi se pare rău să-I slujiți DOMNULUI, alegeți astăzi cui veți sluji: dumnezeilor cărora le-au slujit părinții voștri dincolo de Râu sau dumnezeilor amoriților în a căror țară locuiți. Cât despre mine și casa mea, noi Îi vom sluji DOMNULUI.”", "Poporul a răspuns: „Departe de noi să-L părăsim pe DOMNUL ca să slujim altor dumnezei!", "Căci DOMNUL, Dumnezeul nostru, este Cel care ne-a scos pe noi și pe părinții noștri din țara Egiptului, din casa sclaviei. El a făcut înaintea ochilor noștri acele semne mari, ne-a păzit pe tot drumul pe care am mers și printre toate popoarele prin mijlocul cărora am trecut.", "DOMNUL a alungat dinaintea noastră toate popoarele, inclusiv pe amoriții care locuiau în țară. De aceea și noi Îi vom sluji DOMNULUI, căci El este Dumnezeul nostru.”", "Iosua a spus poporului: „Nu veți putea să-I slujiți DOMNULUI, căci El este un Dumnezeu sfânt, un Dumnezeu gelos. El nu vă va ierta răzvrătirile și păcatele.", "Dacă Îl părăsiți pe DOMNUL și slujiți dumnezeilor străini, El Se va întoarce împotriva voastră, vă va face rău și vă va nimici, după ce v-a făcut bine.”", "Poporul i-a spus lui Iosua: „Nu! Noi Îi vom sluji DOMNULUI.”", "Iosua a spus poporului: „Voi sunteți martori împotriva voastră înșivă că L-ați ales pe DOMNUL ca să-I slujiți.” Ei au răspuns: „Suntem martori.”", "„Acum, îndepărtați dumnezeii străini care sunt în mijlocul vostru și înclinați-vă inima spre DOMNUL, Dumnezeul lui Israel.”", "Poporul i-a spus lui Iosua: „Îi vom sluji DOMNULUI, Dumnezeul nostru, și vom asculta de glasul Lui.”", "În ziua aceea, Iosua a încheiat un legământ cu poporul și a stabilit pentru el o poruncă și o hotărâre la Sihem.", "Iosua a scris aceste cuvinte în Cartea Legii lui Dumnezeu. A luat o piatră mare și a ridicat-o acolo, sub stejarul care era lângă sanctuarul DOMNULUI.", "Iosua a spus întregului popor: „Iată, piatra aceasta va fi martoră împotriva noastră, căci a auzit toate cuvintele pe care ni le-a spus DOMNUL. Ea va fi martoră împotriva voastră, ca să nu-L tăgăduiți pe Dumnezeul vostru.”", "Apoi Iosua a trimis poporul, pe fiecare la moștenirea lui.", "După aceste lucruri, Iosua, fiul lui Nun, slujitorul DOMNULUI, a murit la vârsta de o sută zece ani.", "L-au înmormântat pe teritoriul moștenirii sale, la Timnat-Serah, în regiunea muntoasă a lui Efraim, la nord de muntele Gaaș.", "Israel I-a slujit DOMNULUI în toate zilele lui Iosua și în toate zilele bătrânilor care au trăit după Iosua și care cunoșteau toată lucrarea pe care o făcuse DOMNUL pentru Israel.", "Au înmormântat la Sihem oasele lui Iosif, pe care fiii lui Israel le aduseseră din Egipt, în partea de ogor pe care Iacov o cumpărase de la fiii lui Hamor, tatăl lui Sihem, cu o sută de chesita. Ele au devenit moștenirea fiilor lui Iosif.", "Eleazar, fiul lui Aaron, a murit. L-au înmormântat pe dealul lui Fineas, fiul său, care îi fusese dat în regiunea muntoasă a lui Efraim."],
  },
}
